#[derive(Debug, Error, PartialEq, Eq)]
pub enum ChainLogAuditError {
    #[error("invalid bounded block interval or RPC endpoint")]
    InvalidInput,
    #[error("one chain RPC provider is unavailable")]
    Unavailable,
    #[error("one chain RPC returned an invalid or unfinalized response")]
    Unverified,
    #[error("chain RPC providers disagree about the canonical interval or logs")]
    Divergent,
}

/// Outcome of the transaction verifier's explicit per-operation limits.
#[derive(Debug, Error, PartialEq, Eq)]
pub enum BoundedTransactionVerificationError {
    #[error("transaction verification RPC request budget exhausted")]
    RequestBudgetExceeded,
    #[error("transaction verification exceeded its total deadline")]
    Timeout,
    #[error(transparent)]
    Verification(ChainLogAuditError),
}

