#[derive(Debug, Error, Clone, Copy, PartialEq, Eq)]
#[error("transaction verification RPC request budget exhausted")]
pub enum TransactionRequestBudgetError {
    Exceeded,
}

/// A cloneable actual-RPC-send budget shared by all transaction checks in one
/// candidate operation. It retains no evidence and is not shared across candidates.
#[derive(Clone)]
pub struct TransactionRequestBudget(Arc<OperationRequestBudget>);

impl TransactionRequestBudget {
    #[must_use]
    pub fn new(limit: usize) -> Self {
        Self(Arc::new(OperationRequestBudget::new(limit)))
    }

    /// Reserve one actual RPC send; reservation happens immediately before send.
    pub fn try_reserve_request(&self) -> Result<(), TransactionRequestBudgetError> {
        self.0
            .reserve()
            .map_err(|()| TransactionRequestBudgetError::Exceeded)
    }

    #[must_use]
    pub fn reserved_requests(&self) -> usize {
        self.0.reserved.load(Ordering::Acquire)
    }

    #[must_use]
    pub fn is_exhausted(&self) -> bool {
        *self.0.exhaustion.borrow()
    }

    fn inner(&self) -> Arc<OperationRequestBudget> {
        self.0.clone()
    }
}

struct OperationRequestBudget {
    limit: usize,
    reserved: AtomicUsize,
    exhaustion: watch::Sender<bool>,
}

impl OperationRequestBudget {
    fn new(limit: usize) -> Self {
        let (exhaustion, _) = watch::channel(false);
        Self {
            limit,
            reserved: AtomicUsize::new(0),
            exhaustion,
        }
    }

    fn reserve(&self) -> Result<(), ()> {
        let mut reserved = self.reserved.load(Ordering::Acquire);
        while reserved < self.limit {
            match self.reserved.compare_exchange_weak(
                reserved,
                reserved + 1,
                Ordering::AcqRel,
                Ordering::Acquire,
            ) {
                Ok(_) => return Ok(()),
                Err(actual) => reserved = actual,
            }
        }
        self.exhaustion.send_replace(true);
        Err(())
    }
}

#[cfg(test)]
mod request_budget_tests {
    use super::{OperationRequestBudget, Ordering};
    use std::sync::{Arc, Barrier, atomic::AtomicUsize};

    #[test]
    fn reservations_are_atomic_under_contention_and_do_not_overflow() {
        let budget = Arc::new(OperationRequestBudget::new(1_000));
        let barrier = Arc::new(Barrier::new(16));
        let successes = AtomicUsize::new(0);
        std::thread::scope(|scope| {
            for _ in 0..16 {
                let budget = budget.clone();
                let barrier = barrier.clone();
                let successes = &successes;
                scope.spawn(move || {
                    barrier.wait();
                    for _ in 0..128 {
                        if budget.reserve().is_ok() {
                            successes.fetch_add(1, Ordering::Relaxed);
                        }
                    }
                });
            }
        });
        assert_eq!(successes.load(Ordering::Relaxed), 1_000);
        assert_eq!(budget.reserved.load(Ordering::Acquire), 1_000);
        assert!(*budget.exhaustion.borrow());

        let zero = OperationRequestBudget::new(0);
        assert!(zero.reserve().is_err());
        assert_eq!(zero.reserved.load(Ordering::Acquire), 0);
        assert!(*zero.exhaustion.borrow());

        let maximum = OperationRequestBudget::new(usize::MAX);
        maximum.reserved.store(usize::MAX - 1, Ordering::Release);
        assert!(maximum.reserve().is_ok());
        assert_eq!(maximum.reserved.load(Ordering::Acquire), usize::MAX);
        assert!(!*maximum.exhaustion.borrow());
        assert!(maximum.reserve().is_err());
        assert_eq!(maximum.reserved.load(Ordering::Acquire), usize::MAX);
        assert!(*maximum.exhaustion.borrow());
    }
}

/// A small, read-only evidence summary. Neither this digest nor agreement of
/// two providers certifies equivalent RTDS trades or authorizes gap clearance.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ChainLogEvidence {
    pub from_block: u64,
    pub through_block: u64,
    /// Hash of the block before `from_block`; adjacent verified windows must
    /// link this to the previous window's `canonical_end_hash`.
    pub canonical_parent_hash: String,
    pub canonical_start_hash: String,
    pub canonical_end_hash: String,
    pub filled_logs: usize,
    pub sha256: String,
}

/// A stronger but still single-block, provider-header-anchored diagnostic.
/// Not a full-history cursor, recovered trade set, or gap clearance permit.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ChainReceiptEvidence {
    pub logs: ChainLogEvidence,
    pub verified_receipts_root: String,
    pub receipt_count: usize,
}

/// Every block of one bounded, linked interval has its own receipt-root
/// evidence. Never a replay cursor, an independently anchored chain, or a
/// claim that the five known venues exhaust the RTDS trade domain.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ChainReceiptWindowEvidence {
    pub from_block: u64,
    pub through_block: u64,
    pub blocks: Vec<ChainReceiptEvidence>,
}

/// One transaction's position and raw logs in a verified interval block.
/// Constructed only from the ordered root-verified receipt sequence.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ChainReceiptIntervalTransaction {
    transaction_hash: String,
    transaction_index: u64,
    status: u64,
    receipt_type: u64,
    to: Option<String>,
    input: Option<Vec<u8>>,
    recovered_from: Option<String>,
    value: U256,
    replay_protected_sender: bool,
    native_gas: Option<NativeGasChargeObservation>,
    logs: Vec<ChainReceiptLog>,
    movement_observations: Vec<RawMovementObservation>,
}

/// Root-derived native gas charge for one transaction; no fiat valuation or
/// reimbursement is implied.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NativeGasChargeObservation {
    recovered_sender: String,
    gas_used: U256,
    effective_gas_price: U256,
    charge_base_units: U256,
}

impl NativeGasChargeObservation {
    #[must_use]
    pub fn recovered_sender(&self) -> &str {
        &self.recovered_sender
    }

    #[must_use]
    pub const fn gas_used(&self) -> U256 {
        self.gas_used
    }

    #[must_use]
    pub const fn effective_gas_price(&self) -> U256 {
        self.effective_gas_price
    }

    #[must_use]
    pub const fn charge_base_units(&self) -> U256 {
        self.charge_base_units
    }
}

impl ChainReceiptIntervalTransaction {
    #[must_use]
    pub fn transaction_hash(&self) -> &str {
        &self.transaction_hash
    }
    #[must_use]
    pub const fn transaction_index(&self) -> u64 {
        self.transaction_index
    }
    #[must_use]
    pub const fn status(&self) -> u64 {
        self.status
    }
    #[must_use]
    pub const fn receipt_type(&self) -> u64 {
        self.receipt_type
    }
    #[must_use]
    pub fn logs(&self) -> &[ChainReceiptLog] {
        &self.logs
    }
    #[must_use]
    pub fn movement_observations(&self) -> &[RawMovementObservation] {
        &self.movement_observations
    }
    #[must_use]
    pub fn native_gas(&self) -> Option<&NativeGasChargeObservation> {
        self.native_gas.as_ref()
    }
}

