#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CtfTokenId(U256);

impl CtfTokenId {
    pub fn parse_hex(value: &str) -> Result<Self, ChainLogAuditError> {
        let digits = value
            .strip_prefix("0x")
            .filter(|digits| {
                !digits.is_empty()
                    && digits.len() <= 64
                    && digits.bytes().all(|byte| byte.is_ascii_hexdigit())
            })
            .ok_or(ChainLogAuditError::InvalidInput)?;
        let even_digits = if digits.len() % 2 == 0 {
            digits.to_owned()
        } else {
            format!("0{digits}")
        };
        let bytes = hex::decode(even_digits).map_err(|_| ChainLogAuditError::InvalidInput)?;
        if bytes.len() > 32 {
            return Err(ChainLogAuditError::InvalidInput);
        }
        let mut word = [0_u8; 32];
        word[32 - bytes.len()..].copy_from_slice(&bytes);
        Ok(Self(U256::from_be_slice(&word)))
    }

    #[must_use]
    pub const fn value(self) -> U256 {
        self.0
    }
}

