impl ChainProxyImplementationProof {
    /// Check stored proof nodes and claimed value again after restart. This
    /// does not independently authenticate the claimed header state root.
    pub fn revalidate(&self) -> Result<(), ChainLogAuditError> {
        validate_hex(&self.evidence.block_hash, 32)?;
        if validate_hex(&self.evidence.state_root, 32)? != self.evidence.state_root
            || validate_hex(&self.evidence.implementation, 20)? != self.evidence.implementation
            || verify_proxy_state_proof(&self.evidence.state_root, &self.primary_proof)?
                != self.evidence.implementation
            || verify_proxy_state_proof(&self.evidence.state_root, &self.secondary_proof)?
                != self.evidence.implementation
        {
            return Err(ChainLogAuditError::Unverified);
        }
        Ok(())
    }
}

