/// Candidate multiplicity in this bounded, caller-supplied window only. Even
/// one candidate does not prove RTDS equivalence, completeness or economics.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MakerCandidateMatch {
    InvalidObservation,
    NoCandidate,
    OneCandidate,
    MultipleCandidates { count: usize },
}

/// One raw RTDS tuple's observed multiplicity versus maker-log candidates.
/// Equal counts do not establish feed completeness or one-to-one economics.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MakerTupleCardinality {
    InvalidOrMixedObservations,
    CountsDiffer {
        observations: usize,
        candidate_fills: usize,
    },
    CountsEqualUnverified {
        count: usize,
    },
}

impl ChainMakerWindow {
    /// Diagnostics require the *raw pre-dedup* observations for one tuple.
    /// A rolling RTDS deduplicator may already have discarded equal rows;
    /// even equal counts here cannot certify that no upstream rows were lost.
    #[must_use]
    pub fn maker_tuple_cardinality(&self, observations: &[FirehoseTrade]) -> MakerTupleCardinality {
        let Some(first) = observations.first() else {
            return MakerTupleCardinality::InvalidOrMixedObservations;
        };
        let candidate_fills = match self.maker_candidates(first) {
            MakerCandidateMatch::InvalidObservation => {
                return MakerTupleCardinality::InvalidOrMixedObservations;
            }
            MakerCandidateMatch::NoCandidate => 0,
            MakerCandidateMatch::OneCandidate => 1,
            MakerCandidateMatch::MultipleCandidates { count } => count,
        };
        if observations.iter().skip(1).any(|trade| {
            !trade.proxy_wallet.eq_ignore_ascii_case(&first.proxy_wallet)
                || !trade
                    .transaction_hash
                    .eq_ignore_ascii_case(&first.transaction_hash)
                || trade.token_id != first.token_id
                || trade.condition_id != first.condition_id
                || trade.side != first.side
                || trade.timestamp.timestamp() != first.timestamp.timestamp()
                || trade.price != first.price
                || trade.size != first.size
                || matches!(
                    self.maker_candidates(trade),
                    MakerCandidateMatch::InvalidObservation
                )
        }) {
            return MakerTupleCardinality::InvalidOrMixedObservations;
        }
        if observations.len() == candidate_fills {
            MakerTupleCardinality::CountsEqualUnverified {
                count: candidate_fills,
            }
        } else {
            MakerTupleCardinality::CountsDiffer {
                observations: observations.len(),
                candidate_fills,
            }
        }
    }

    /// Compare only indexed order owner, transaction, token, BUY/SELL and exact
    /// six-decimal share quantity. Aggregate taker-order fills are included;
    /// this says nothing about order role, price, feed cardinality or gap clearance.
    #[must_use]
    pub fn maker_candidates(&self, trade: &FirehoseTrade) -> MakerCandidateMatch {
        let side = match trade.side.as_str() {
            "BUY" => TradeSide::Buy,
            "SELL" => TradeSide::Sell,
            _ => return MakerCandidateMatch::InvalidObservation,
        };
        let units = trade.size * Decimal::from(1_000_000_u64);
        let Some(shares) = (units > Decimal::ZERO && units.fract().is_zero())
            .then(|| units.to_u128())
            .flatten()
        else {
            return MakerCandidateMatch::InvalidObservation;
        };
        if validate_hex(&trade.proxy_wallet, 20).is_err()
            || validate_hex(&trade.transaction_hash, 32).is_err()
            || BigUint::parse_bytes(trade.token_id.as_bytes(), 10).is_none_or(|token| {
                token.to_str_radix(10) != trade.token_id || token == BigUint::from(0_u8)
            })
        {
            return MakerCandidateMatch::InvalidObservation;
        }
        let count = self
            .fills
            .iter()
            .filter(|fill| {
                fill.wallet.eq_ignore_ascii_case(&trade.proxy_wallet)
                    && fill
                        .transaction_hash
                        .eq_ignore_ascii_case(&trade.transaction_hash)
                    && fill.token_id == trade.token_id
                    && fill.side == side
                    && fill.share_base_units == shares
            })
            .count();
        match count {
            0 => MakerCandidateMatch::NoCandidate,
            1 => MakerCandidateMatch::OneCandidate,
            count => MakerCandidateMatch::MultipleCandidates { count },
        }
    }
}

impl ChainLogEvidence {
    /// Checks that two independently verified windows meet without a skipped
    /// block or a broken parent hash. Caller-supplied evidence is not itself
    /// authenticated and this does not clear scanner coverage gaps.
    pub fn follows(&self, previous: &Self) -> Result<(), ChainLogAuditError> {
        if previous.through_block.checked_add(1) != Some(self.from_block) {
            return Err(ChainLogAuditError::InvalidInput);
        }
        if previous.canonical_end_hash != self.canonical_parent_hash {
            return Err(ChainLogAuditError::Divergent);
        }
        Ok(())
    }
}

