    fn movement_topic(signature: &str) -> String {
        format!("0x{}", hex::encode(Keccak256::digest(signature.as_bytes())))
    }

    fn movement_address_topic(byte: u8) -> String {
        format!("0x{}{}", "00".repeat(12), hex::encode([byte; 20]))
    }

    fn movement_word(value: U256) -> Vec<u8> {
        value.to_be_bytes::<32>().to_vec()
    }

    fn address_topic(address: &str) -> String {
        format!("0x{}{}", "00".repeat(12), &address[2..])
    }

    fn test_v1_fill_order_input(
        maker: &str,
        token_id: U256,
        maker_amount: U256,
        taker_amount: U256,
        fee_rate_bps: U256,
        side: V1DirectFillSide,
        fill_amount: U256,
    ) -> Vec<u8> {
        let address_word = |address: &str| {
            let mut word = [0_u8; 32];
            word[12..].copy_from_slice(&hex::decode(&address[2..]).unwrap());
            U256::from_be_slice(&word)
        };
        let mut args = Vec::new();
        args.extend(movement_word(U256::from(64_u64)));
        args.extend(movement_word(fill_amount));
        for word in [
            U256::ZERO,
            address_word(maker),
            address_word(maker),
            U256::ZERO,
            token_id,
            maker_amount,
            taker_amount,
            U256::ZERO,
            U256::ZERO,
            fee_rate_bps,
            match side {
                V1DirectFillSide::Buy => U256::ZERO,
                V1DirectFillSide::Sell => U256::ONE,
            },
            U256::ZERO,
            U256::from(13 * 32),
        ] {
            args.extend(movement_word(word));
        }
        args.extend(movement_word(U256::ZERO));
        [V1_FILL_ORDER_SELECTOR.to_vec(), args].concat()
    }

    fn test_v1_fill_orders_input_many(order_inputs: &[&[u8]], fill_amounts: &[U256]) -> Vec<u8> {
        assert_eq!(order_inputs.len(), fill_amounts.len());
        assert!(!order_inputs.is_empty());
        let tuples = order_inputs
            .iter()
            .map(|input| &input[4 + 64..])
            .collect::<Vec<_>>();
        let heads_start = 64 + 32;
        let mut cursor = heads_start + tuples.len() * 32;
        let mut args = Vec::new();
        args.extend(movement_word(U256::from(64_u64)));
        let fill_amounts_offset_index = args.len();
        args.extend(movement_word(U256::ZERO));
        args.extend(movement_word(U256::from(tuples.len())));
        for tuple in &tuples {
            args.extend(movement_word(U256::from(cursor - heads_start)));
            cursor += tuple.len();
        }
        for tuple in tuples {
            args.extend_from_slice(tuple);
        }
        args[fill_amounts_offset_index..fill_amounts_offset_index + 32]
            .copy_from_slice(&movement_word(U256::from(cursor)));
        args.extend(movement_word(U256::from(fill_amounts.len())));
        for amount in fill_amounts {
            args.extend(movement_word(*amount));
        }
        [V1_FILL_ORDERS_SELECTOR.to_vec(), args].concat()
    }

    fn test_v1_match_orders_input(
        taker_order_input: &[u8],
        maker_order_input: &[u8],
        taker_fill_amount: U256,
        maker_fill_amount: U256,
    ) -> Vec<u8> {
        test_v1_match_orders_input_many(
            taker_order_input,
            &[maker_order_input],
            taker_fill_amount,
            &[maker_fill_amount],
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn test_multi_maker_match_transaction(
        active_maker: &str,
        passive_maker: &str,
        active_making: U256,
        active_taking_limit: U256,
        maker_makings: &[U256],
        maker_takings: &[U256],
        active_side: V1DirectFillSide,
        key_byte: u8,
    ) -> (ChainReceiptIntervalTransaction, Value) {
        test_multi_maker_match_transaction_for_token(
            test_token_id().value(),
            active_maker,
            passive_maker,
            active_making,
            active_taking_limit,
            maker_makings,
            maker_takings,
            active_side,
            key_byte,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn test_multi_maker_match_transaction_for_token(
        token: U256,
        active_maker: &str,
        passive_maker: &str,
        active_making: U256,
        active_taking_limit: U256,
        maker_makings: &[U256],
        maker_takings: &[U256],
        active_side: V1DirectFillSide,
        key_byte: u8,
    ) -> (ChainReceiptIntervalTransaction, Value) {
        assert_eq!(maker_makings.len(), maker_takings.len());
        let active_input = test_v1_fill_order_input(
            active_maker,
            token,
            active_making,
            active_taking_limit,
            U256::from(100_u64),
            active_side,
            active_making,
        );
        let maker_inputs: Vec<Vec<u8>> = maker_makings
            .iter()
            .zip(maker_takings)
            .enumerate()
            .map(|(index, (making, taking))| {
                let mut input = test_v1_fill_order_input(
                    passive_maker,
                    token,
                    *making,
                    *taking,
                    U256::from(100_u64),
                    match active_side {
                        V1DirectFillSide::Buy => V1DirectFillSide::Sell,
                        V1DirectFillSide::Sell => V1DirectFillSide::Buy,
                    },
                    *making,
                );
                input[4 + 64..4 + 96].copy_from_slice(&movement_word(U256::from(index + 1)));
                input
            })
            .collect();
        let maker_refs: Vec<&[u8]> = maker_inputs.iter().map(Vec::as_slice).collect();
        let input = test_v1_match_orders_input_many(
            &active_input,
            &maker_refs,
            active_making,
            maker_makings,
        );
        let (signed_transaction, operator) =
            signed_polygon_transaction_with_key(EXCHANGES[0], &input, key_byte);
        let call = decode_v1_match_orders_call(&input).unwrap();
        let active_hash = v1_order_hash(&call.taker_order).unwrap();
        let (active_maker_asset, active_taker_asset) = order_asset_ids(&call.taker_order);
        let maker_hashes: Vec<String> = call
            .maker_orders
            .iter()
            .map(|order| v1_order_hash(order).unwrap())
            .collect();
        let active_taking = call.maker_fill_amounts.iter().copied().sum::<U256>();
        let active_fee = calculate_v1_match_order_fee(
            &call.taker_order,
            call.taker_fill_amount,
            active_taking,
            V1MatchFeePrice::ActualFill,
        )
        .unwrap();
        let active_net = active_taking - active_fee;
        let mut logs = vec![test_asset_transfer(
            active_maker_asset,
            active_maker,
            EXCHANGES[0],
            active_making,
            0,
        )];
        let mut index = 1;
        for (maker, maker_hash, maker_fill) in call
            .maker_orders
            .iter()
            .zip(&maker_hashes)
            .zip(&call.maker_fill_amounts)
            .map(|((order, hash), fill)| (order, hash, fill))
        {
            let maker_taking =
                checked_mul_div(*maker_fill, maker.taker_amount, maker.maker_amount).unwrap();
            let maker_fee = calculate_v1_match_order_fee(
                maker,
                *maker_fill,
                maker_taking,
                V1MatchFeePrice::SignedOrder,
            )
            .unwrap();
            let (maker_asset, taker_asset) = order_asset_ids(maker);
            logs.push(test_asset_transfer(
                maker_asset,
                &maker.maker,
                EXCHANGES[0],
                *maker_fill,
                index,
            ));
            index += 1;
            logs.push(test_asset_transfer(
                taker_asset,
                EXCHANGES[0],
                &maker.maker,
                maker_taking - maker_fee,
                index,
            ));
            index += 1;
            if !maker_fee.is_zero() {
                logs.push(test_asset_transfer(
                    taker_asset,
                    EXCHANGES[0],
                    &operator,
                    maker_fee,
                    index,
                ));
                index += 1;
                logs.push(test_fee_charged_log(
                    &operator,
                    taker_asset,
                    maker_fee,
                    index,
                ));
                index += 1;
            }
            logs.push(test_order_filled_log(
                maker_hash,
                &maker.maker,
                active_maker,
                maker_asset,
                taker_asset,
                *maker_fill,
                maker_taking,
                maker_fee,
                index,
            ));
            index += 1;
        }
        logs.push(test_asset_transfer(
            active_taker_asset,
            EXCHANGES[0],
            active_maker,
            active_net,
            index,
        ));
        index += 1;
        if !active_fee.is_zero() {
            logs.push(test_asset_transfer(
                active_taker_asset,
                EXCHANGES[0],
                &operator,
                active_fee,
                index,
            ));
            index += 1;
            logs.push(test_fee_charged_log(
                &operator,
                active_taker_asset,
                active_fee,
                index,
            ));
            index += 1;
        }
        let active_refund = active_making - maker_takings.iter().copied().sum::<U256>();
        if !active_refund.is_zero() {
            logs.push(test_asset_transfer(
                active_maker_asset,
                EXCHANGES[0],
                active_maker,
                active_refund,
                index,
            ));
            index += 1;
        }
        logs.push(test_order_filled_log(
            &active_hash,
            active_maker,
            EXCHANGES[0],
            active_maker_asset,
            active_taker_asset,
            active_making,
            active_taking,
            active_fee,
            index,
        ));
        index += 1;
        let mut matched_data = Vec::new();
        matched_data.extend(movement_word(active_maker_asset));
        matched_data.extend(movement_word(active_taker_asset));
        matched_data.extend(movement_word(active_making));
        matched_data.extend(movement_word(active_taking));
        logs.push(test_indexed_event_log(
            EXCHANGES[0],
            &v1_event_topic("OrdersMatched(bytes32,address,uint256,uint256,uint256,uint256)"),
            &[active_hash, test_address_topic(active_maker)],
            matched_data,
            index,
        ));
        let transaction_hash = format!(
            "{:#x}",
            encode_signed_transaction(&signed_transaction).unwrap().hash
        );
        (
            ChainReceiptIntervalTransaction {
                transaction_hash,
                transaction_index: 0,
                status: 1,
                receipt_type: 2,
                to: Some(EXCHANGES[0].to_owned()),
                input: Some(input),
                recovered_from: Some(operator),
                value: U256::ZERO,
                replay_protected_sender: true,
                native_gas: None,
                movement_observations: decode_movement_observations(&logs),
                logs,
            },
            signed_transaction,
        )
    }

    fn test_binary_balance_for_asset(
        positions: [U256; 2],
        cash: U256,
        position_ids: [U256; 2],
        asset: U256,
    ) -> Option<U256> {
        if asset.is_zero() {
            Some(cash)
        } else {
            position_ids
                .iter()
                .position(|id| *id == asset)
                .map(|index| positions[index])
        }
    }

    fn test_binary_move_balance_for_asset(
        positions: &mut [U256; 2],
        cash: &mut U256,
        position_ids: [U256; 2],
        asset: U256,
        inflow: bool,
        amount: U256,
    ) -> Option<()> {
        let target = if asset.is_zero() {
            cash
        } else {
            &mut positions[position_ids.iter().position(|id| *id == asset)?]
        };
        *target = if inflow {
            target.checked_add(amount)?
        } else {
            target.checked_sub(amount)?
        };
        Some(())
    }

    #[allow(clippy::too_many_arguments)]
    fn test_binary_match_transaction_for_orders(
        active_order_input: &[u8],
        active_fill: U256,
        passive_order_inputs: &[&[u8]],
        passive_fills: &[U256],
        opening_exchange_positions: [U256; 2],
        opening_exchange_cash: U256,
        identity: &ctf_position_identity::DerivedRootBinaryIdentity,
        key_byte: u8,
    ) -> (ChainReceiptIntervalTransaction, Value, [U256; 2], U256) {
        assert_eq!(passive_order_inputs.len(), passive_fills.len());
        let input = test_v1_match_orders_input_many(
            active_order_input,
            passive_order_inputs,
            active_fill,
            passive_fills,
        );
        let (signed_transaction, operator) =
            signed_polygon_transaction_with_key(EXCHANGES[0], &input, key_byte);
        let call = decode_v1_match_orders_call(&input).unwrap();
        let position_ids = identity.position_ids.map(|id| U256::from_be_bytes(id.0));
        let mut positions = opening_exchange_positions;
        let mut cash = opening_exchange_cash;
        let mut logs = Vec::new();
        let mut index = 0_u64;

        let (active_maker_asset, active_taker_asset) = order_asset_ids(&call.taker_order);
        logs.push(test_asset_transfer(
            active_maker_asset,
            &call.taker_order.maker,
            EXCHANGES[0],
            active_fill,
            index,
        ));
        index += 1;
        test_binary_move_balance_for_asset(
            &mut positions,
            &mut cash,
            position_ids,
            active_maker_asset,
            true,
            active_fill,
        )
        .unwrap();
        for (order, fill) in call.maker_orders.iter().zip(&call.maker_fill_amounts) {
            let (maker_asset, taker_asset) = order_asset_ids(order);
            logs.push(test_asset_transfer(
                maker_asset,
                &order.maker,
                EXCHANGES[0],
                *fill,
                index,
            ));
            index += 1;
            test_binary_move_balance_for_asset(
                &mut positions,
                &mut cash,
                position_ids,
                maker_asset,
                true,
                *fill,
            )
            .unwrap();
            let taking = checked_mul_div(*fill, order.taker_amount, order.maker_amount).unwrap();
            let fee =
                calculate_v1_match_order_fee(order, *fill, taking, V1MatchFeePrice::SignedOrder)
                    .unwrap();
            if order.side == call.taker_order.side {
                let amount = if order.side == V1DirectFillSide::Buy {
                    taking
                } else {
                    *fill
                };
                if order.side == V1DirectFillSide::Buy {
                    logs.push(test_erc20_transfer(
                        EXCHANGES[0],
                        CTF_CONDITIONAL_TOKENS_ADDRESS,
                        amount,
                        index,
                    ));
                    index += 1;
                    logs.push(test_erc20_approval(
                        EXCHANGES[0],
                        CTF_CONDITIONAL_TOKENS_ADDRESS,
                        U256::ZERO,
                        index,
                    ));
                    index += 1;
                    let ids = position_ids;
                    logs.push(test_transfer_batch(
                        EXCHANGES[0],
                        &zero_address(),
                        EXCHANGES[0],
                        ids,
                        [amount; 2],
                        index,
                    ));
                    index += 1;
                    logs.push(test_ctf_operation_event(
                        true,
                        identity.condition_id,
                        amount,
                        index,
                    ));
                    index += 1;
                    cash = cash.checked_sub(amount).expect("split has collateral");
                    for balance in &mut positions {
                        *balance = balance.checked_add(amount).unwrap();
                    }
                } else {
                    logs.push(test_transfer_batch(
                        EXCHANGES[0],
                        EXCHANGES[0],
                        &zero_address(),
                        position_ids,
                        [amount; 2],
                        index,
                    ));
                    index += 1;
                    logs.push(test_erc20_transfer(
                        CTF_CONDITIONAL_TOKENS_ADDRESS,
                        EXCHANGES[0],
                        amount,
                        index,
                    ));
                    index += 1;
                    logs.push(test_ctf_operation_event(
                        false,
                        identity.condition_id,
                        amount,
                        index,
                    ));
                    index += 1;
                    for balance in &mut positions {
                        *balance = balance.checked_sub(amount).expect("merge has positions");
                    }
                    cash = cash.checked_add(amount).unwrap();
                }
            }
            logs.push(test_asset_transfer(
                taker_asset,
                EXCHANGES[0],
                &order.maker,
                taking - fee,
                index,
            ));
            index += 1;
            test_binary_move_balance_for_asset(
                &mut positions,
                &mut cash,
                position_ids,
                taker_asset,
                false,
                taking,
            )
            .unwrap();
            if !fee.is_zero() {
                logs.push(test_asset_transfer(
                    taker_asset,
                    EXCHANGES[0],
                    &operator,
                    fee,
                    index,
                ));
                index += 1;
                logs.push(test_fee_charged_log(&operator, taker_asset, fee, index));
                index += 1;
            }
            logs.push(test_order_filled_log(
                &v1_order_hash(order).unwrap(),
                &order.maker,
                &call.taker_order.maker,
                maker_asset,
                taker_asset,
                *fill,
                taking,
                fee,
                index,
            ));
            index += 1;
        }
        let active_taking =
            test_binary_balance_for_asset(positions, cash, position_ids, active_taker_asset)
                .unwrap();
        let active_fee = calculate_v1_match_order_fee(
            &call.taker_order,
            active_fill,
            active_taking,
            V1MatchFeePrice::ActualFill,
        )
        .unwrap();
        test_binary_move_balance_for_asset(
            &mut positions,
            &mut cash,
            position_ids,
            active_taker_asset,
            false,
            active_taking,
        )
        .unwrap();
        logs.push(test_asset_transfer(
            active_taker_asset,
            EXCHANGES[0],
            &call.taker_order.maker,
            active_taking - active_fee,
            index,
        ));
        index += 1;
        if !active_fee.is_zero() {
            logs.push(test_asset_transfer(
                active_taker_asset,
                EXCHANGES[0],
                &operator,
                active_fee,
                index,
            ));
            index += 1;
            logs.push(test_fee_charged_log(
                &operator,
                active_taker_asset,
                active_fee,
                index,
            ));
            index += 1;
        }
        let refund =
            test_binary_balance_for_asset(positions, cash, position_ids, active_maker_asset)
                .unwrap();
        if !refund.is_zero() {
            logs.push(test_asset_transfer(
                active_maker_asset,
                EXCHANGES[0],
                &call.taker_order.maker,
                refund,
                index,
            ));
            index += 1;
            test_binary_move_balance_for_asset(
                &mut positions,
                &mut cash,
                position_ids,
                active_maker_asset,
                false,
                refund,
            )
            .unwrap();
        }
        let (active_maker_asset, active_taker_asset) = order_asset_ids(&call.taker_order);
        logs.push(test_order_filled_log(
            &v1_order_hash(&call.taker_order).unwrap(),
            &call.taker_order.maker,
            EXCHANGES[0],
            active_maker_asset,
            active_taker_asset,
            active_fill,
            active_taking,
            active_fee,
            index,
        ));
        index += 1;
        let mut matched_data = Vec::new();
        matched_data.extend(movement_word(active_maker_asset));
        matched_data.extend(movement_word(active_taker_asset));
        matched_data.extend(movement_word(active_fill));
        matched_data.extend(movement_word(active_taking));
        logs.push(test_indexed_event_log(
            EXCHANGES[0],
            &v1_event_topic("OrdersMatched(bytes32,address,uint256,uint256,uint256,uint256)"),
            &[
                v1_order_hash(&call.taker_order).unwrap(),
                test_address_topic(&call.taker_order.maker),
            ],
            matched_data,
            index,
        ));
        let logs = insert_v1_binary_transfer_from_approvals(logs);
        let movement_observations = decode_movement_observations(&logs);
        let transaction_hash = format!(
            "{:#x}",
            encode_signed_transaction(&signed_transaction).unwrap().hash
        );
        (
            ChainReceiptIntervalTransaction {
                transaction_hash,
                transaction_index: 0,
                status: 1,
                receipt_type: 2,
                to: Some(EXCHANGES[0].to_owned()),
                input: Some(input),
                recovered_from: Some(operator),
                value: U256::ZERO,
                replay_protected_sender: true,
                native_gas: None,
                logs,
                movement_observations,
            },
            signed_transaction,
            positions,
            cash,
        )
    }

    fn test_v1_match_orders_input_many(
        taker_order_input: &[u8],
        maker_order_inputs: &[&[u8]],
        taker_fill_amount: U256,
        maker_fill_amounts: &[U256],
    ) -> Vec<u8> {
        assert_eq!(maker_order_inputs.len(), maker_fill_amounts.len());
        let taker_order = &taker_order_input[4 + 64..];
        let maker_tuples: Vec<&[u8]> = maker_order_inputs
            .iter()
            .map(|order| &order[4 + 64..])
            .collect();
        let maker_orders_offset = 128 + taker_order.len();
        let maker_data_offset = maker_order_inputs.len() * 32;
        let mut args = Vec::new();
        args.extend(movement_word(U256::from(128_u64)));
        args.extend(movement_word(U256::from(maker_orders_offset)));
        args.extend(movement_word(taker_fill_amount));
        args.extend(movement_word(U256::ZERO));
        args.extend_from_slice(taker_order);
        args.extend(movement_word(U256::from(maker_order_inputs.len())));
        let mut relative_tuple_offset = maker_data_offset;
        for tuple in &maker_tuples {
            args.extend(movement_word(U256::from(relative_tuple_offset)));
            relative_tuple_offset += tuple.len();
        }
        for tuple in &maker_tuples {
            args.extend_from_slice(tuple);
        }
        let maker_fill_amounts_offset = maker_orders_offset
            + 32
            + maker_data_offset
            + maker_tuples.iter().map(|tuple| tuple.len()).sum::<usize>();
        let offset_word = 3 * 32;
        args[offset_word..offset_word + 32]
            .copy_from_slice(&movement_word(U256::from(maker_fill_amounts_offset)));
        args.extend(movement_word(U256::from(maker_fill_amounts.len())));
        for amount in maker_fill_amounts {
            args.extend(movement_word(*amount));
        }
        [V1_MATCH_ORDERS_SELECTOR.to_vec(), args].concat()
    }

    fn signed_polygon_native_gas_transaction(
        transaction_type: u8,
        key_byte: u8,
        nonce: u64,
        gas_limit: u64,
        gas_price: U256,
        max_fee: U256,
        max_priority_fee: U256,
    ) -> (Value, String) {
        let key = SigningKey::from_bytes((&[key_byte; 32]).into()).unwrap();
        let public_key = key.verifying_key().to_encoded_point(false);
        let public_key_hash = Keccak256::digest(&public_key.as_bytes()[1..]);
        let from = format!("0x{}", hex::encode(&public_key_hash[12..]));
        let to_bytes = hex::decode("0000000000000000000000000000000000000002").unwrap();
        let signing_fields = match transaction_type {
            0 => vec![
                rlp_u256(U256::from(nonce)),
                rlp_u256(gas_price),
                rlp_u256(U256::from(gas_limit)),
                alloy_rlp::encode(to_bytes.as_slice()),
                rlp_u256(U256::ZERO),
                alloy_rlp::encode([]),
            ],
            1 => vec![
                rlp_u256(U256::from(CHAIN_ID)),
                rlp_u256(U256::from(nonce)),
                rlp_u256(gas_price),
                rlp_u256(U256::from(gas_limit)),
                alloy_rlp::encode(to_bytes.as_slice()),
                rlp_u256(U256::ZERO),
                alloy_rlp::encode([]),
                rlp_list(&[]),
            ],
            2 => vec![
                rlp_u256(U256::from(CHAIN_ID)),
                rlp_u256(U256::from(nonce)),
                rlp_u256(max_priority_fee),
                rlp_u256(max_fee),
                rlp_u256(U256::from(gas_limit)),
                alloy_rlp::encode(to_bytes.as_slice()),
                rlp_u256(U256::ZERO),
                alloy_rlp::encode([]),
                rlp_list(&[]),
            ],
            _ => panic!("fixture supports only transaction types 0, 1, and 2"),
        };
        let mut signing_payload = Vec::new();
        if transaction_type == 0 {
            let mut replay_protected = signing_fields.clone();
            replay_protected.extend([
                rlp_u256(U256::from(CHAIN_ID)),
                rlp_u256(U256::ZERO),
                rlp_u256(U256::ZERO),
            ]);
            signing_payload = rlp_list(&replay_protected);
        } else {
            signing_payload.push(transaction_type);
            signing_payload.extend(rlp_list(&signing_fields));
        }
        let (signature, recovery_id) = key
            .sign_digest_recoverable(Keccak256::new_with_prefix(signing_payload))
            .unwrap();
        assert!(!recovery_id.is_x_reduced());
        let parity = u64::from(recovery_id.is_y_odd());
        let signature_bytes = signature.to_bytes();
        let r = U256::from_be_slice(&signature_bytes[..32]);
        let s = U256::from_be_slice(&signature_bytes[32..]);
        let mut transaction = json!({
            "nonce": format!("{nonce:#x}"),
            "gas": format!("{gas_limit:#x}"),
            "to": "0x0000000000000000000000000000000000000002",
            "value": "0x0",
            "input": "0x",
            "from": from,
            "r": format!("0x{r:x}"),
            "s": format!("0x{s:x}")
        });
        match transaction_type {
            0 => {
                let v = 35 + 2 * CHAIN_ID + parity;
                transaction["gasPrice"] = json!(format!("{gas_price:#x}"));
                transaction["v"] = json!(format!("{v:#x}"));
            }
            1 => {
                transaction["type"] = json!("0x1");
                transaction["chainId"] = json!(format!("{CHAIN_ID:#x}"));
                transaction["gasPrice"] = json!(format!("{gas_price:#x}"));
                transaction["accessList"] = json!([]);
                transaction["yParity"] = json!(format!("{parity:#x}"));
            }
            2 => {
                transaction["type"] = json!("0x2");
                transaction["chainId"] = json!(format!("{CHAIN_ID:#x}"));
                transaction["maxFeePerGas"] = json!(format!("{max_fee:#x}"));
                transaction["maxPriorityFeePerGas"] = json!(format!("{max_priority_fee:#x}"));
                transaction["accessList"] = json!([]);
                transaction["yParity"] = json!(format!("{parity:#x}"));
            }
            _ => unreachable!(),
        }
        (transaction, from)
    }

    fn signed_polygon_transaction(to: &str, input: &[u8]) -> (Value, String) {
        signed_polygon_transaction_with_key(to, input, 0x42)
    }

    pub(in crate::chain_log_audit) fn signed_polygon_transaction_with_key(
        to: &str,
        input: &[u8],
        key_byte: u8,
    ) -> (Value, String) {
        signed_polygon_transaction_with_key_and_gas_price(to, input, key_byte, U256::ONE)
    }

    fn signed_polygon_transaction_with_key_and_gas_price(
        to: &str,
        input: &[u8],
        key_byte: u8,
        gas_price: U256,
    ) -> (Value, String) {
        let key = SigningKey::from_bytes((&[key_byte; 32]).into()).unwrap();
        let public_key = key.verifying_key().to_encoded_point(false);
        let public_key_hash = Keccak256::digest(&public_key.as_bytes()[1..]);
        let from = format!("0x{}", hex::encode(&public_key_hash[12..]));
        let to_bytes = hex::decode(&to[2..]).unwrap();
        let signing_fields = [
            rlp_u256(U256::ZERO),
            rlp_u256(gas_price),
            rlp_u256(U256::from(100_000_u64)),
            alloy_rlp::encode(to_bytes.as_slice()),
            rlp_u256(U256::ZERO),
            alloy_rlp::encode(input),
            rlp_u256(U256::from(CHAIN_ID)),
            rlp_u256(U256::ZERO),
            rlp_u256(U256::ZERO),
        ];
        let signing_payload = rlp_list(&signing_fields);
        let (signature, recovery_id) = key
            .sign_digest_recoverable(Keccak256::new_with_prefix(signing_payload))
            .unwrap();
        assert!(!recovery_id.is_x_reduced());
        let parity = u64::from(recovery_id.is_y_odd());
        let signature_bytes = signature.to_bytes();
        let r = U256::from_be_slice(&signature_bytes[..32]);
        let s = U256::from_be_slice(&signature_bytes[32..]);
        let transaction = json!({
            "nonce":"0x0", "gasPrice":format!("{gas_price:#x}"), "gas":"0x186a0",
            "to":to, "value":"0x0", "input":format!("0x{}", hex::encode(input)),
            "v":format!("0x{:x}", 35 + 2 * CHAIN_ID + parity),
            "r":format!("0x{r:x}"), "s":format!("0x{s:x}"), "from":from
        });
        (transaction, from)
    }

    fn batch_data(ids: &[U256], amounts: &[U256]) -> Vec<u8> {
        let amounts_offset = 96 + ids.len() * 32;
        let mut data = Vec::new();
        data.extend(movement_word(U256::from(64)));
        data.extend(movement_word(U256::from(amounts_offset)));
        data.extend(movement_word(U256::from(ids.len())));
        for id in ids {
            data.extend(movement_word(*id));
        }
        data.extend(movement_word(U256::from(amounts.len())));
        for amount in amounts {
            data.extend(movement_word(*amount));
        }
        data
    }

