    fn insert_usdc_transfer_from_approvals(logs: Vec<ChainReceiptLog>) -> Vec<ChainReceiptLog> {
        let mut ordered = Vec::with_capacity(logs.len() * 2);
        for log in logs {
            let approval = if log.address.eq_ignore_ascii_case(USDC_E_PROXY_ADDRESS) {
                match decode_erc20_transfer(&log) {
                    Ok(ObservedAssetMovement::Erc20Transfer { from, to, amount })
                        if to.eq_ignore_ascii_case(EXCHANGES[0])
                            && !from.eq_ignore_ascii_case(EXCHANGES[0]) =>
                    {
                        Some(test_erc20_approval(&from, EXCHANGES[0], amount, 0))
                    }
                    _ => None,
                }
            } else {
                None
            };
            ordered.push(log);
            if let Some(approval) = approval {
                ordered.push(approval);
            }
        }
        for (index, log) in ordered.iter_mut().enumerate() {
            log.block_log_index = index as u64;
        }
        ordered
    }

