    #[test]
    fn movement_topics_match_the_pinned_transfer_signatures() {
        assert_eq!(
            movement_topic("Transfer(address,address,uint256)"),
            ERC20_TRANSFER
        );
        assert_eq!(
            movement_topic("TransferSingle(address,address,address,uint256,uint256)"),
            ERC1155_TRANSFER_SINGLE
        );
        assert_eq!(
            movement_topic("TransferBatch(address,address,address,uint256[],uint256[])"),
            ERC1155_TRANSFER_BATCH
        );
    }

    #[test]
    fn movement_decoder_preserves_full_width_transfer_values_and_raw_zero_addresses() {
        let transfer = raw_movement_log(
            ERC20_TRANSFER,
            &[movement_address_topic(0), movement_address_topic(0xab)],
            movement_word(U256::MAX),
        );
        let single = raw_movement_log(
            ERC1155_TRANSFER_SINGLE,
            &[
                movement_address_topic(0xef),
                movement_address_topic(0),
                movement_address_topic(0xcd),
            ],
            [movement_word(U256::MAX), movement_word(U256::ZERO)].concat(),
        );
        let decoded = decode_movement_observations(&[transfer, single]);
        assert_eq!(decoded.len(), 2);
        assert_eq!(decoded[0].log_index(), 17);
        assert_eq!(decoded[0].transaction_index(), 3);
        assert_eq!(
            decoded[0].transaction_hash(),
            format!("0x{}", "bb".repeat(32))
        );
        assert!(matches!(
            decoded[0].status(),
            MovementObservationStatus::Decoded(ObservedAssetMovement::Erc20Transfer {
                from, to, amount
            }) if from == "0x0000000000000000000000000000000000000000"
                && to == "0xabababababababababababababababababababab"
                && *amount == U256::MAX
        ));
        assert!(matches!(
            decoded[1].status(),
            MovementObservationStatus::Decoded(ObservedAssetMovement::Erc1155TransferSingle {
                operator, from, to, id, amount
            }) if operator == "0xefefefefefefefefefefefefefefefefefefefef"
                && from == "0x0000000000000000000000000000000000000000"
                && to == "0xcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcd"
                && *id == U256::MAX && *amount == U256::ZERO
        ));
        assert_eq!(decoded[0].emitter(), format!("0x{}", "ee".repeat(20)));
    }

    #[test]
    fn movement_decoder_supports_equal_batch_duplicates_and_empty_batches() {
        let ids = [U256::from(7), U256::MAX, U256::from(7)];
        let amounts = [U256::from(1), U256::MAX, U256::from(1)];
        let batch = raw_movement_log(
            ERC1155_TRANSFER_BATCH,
            &[
                movement_address_topic(0xef),
                movement_address_topic(0xab),
                movement_address_topic(0xcd),
            ],
            batch_data(&ids, &amounts),
        );
        let empty = raw_movement_log(
            ERC1155_TRANSFER_BATCH,
            &[
                movement_address_topic(0xef),
                movement_address_topic(0xab),
                movement_address_topic(0xcd),
            ],
            batch_data(&[], &[]),
        );
        let decoded = decode_movement_observations(&[batch, empty]);
        assert!(matches!(
            decoded[0].status(),
            MovementObservationStatus::Decoded(ObservedAssetMovement::Erc1155TransferBatch {
                ids: decoded_ids, amounts: decoded_amounts, ..
            }) if decoded_ids == &ids && decoded_amounts == &amounts
        ));
        assert!(matches!(
            decoded[1].status(),
            MovementObservationStatus::Decoded(ObservedAssetMovement::Erc1155TransferBatch {
                ids, amounts, ..
            }) if ids.is_empty() && amounts.is_empty()
        ));
    }

    #[test]
    fn recognized_malformed_movement_topics_remain_explicitly_unsupported() {
        let indexed = [
            movement_address_topic(0xef),
            movement_address_topic(0xab),
            movement_address_topic(0xcd),
        ];
        let erc721_shaped = raw_movement_log(
            ERC20_TRANSFER,
            &[
                movement_address_topic(0xab),
                movement_address_topic(0xcd),
                movement_address_topic(0x12),
            ],
            Vec::new(),
        );
        let bad_padding = raw_movement_log(
            ERC20_TRANSFER,
            &[
                format!("0x{}", "01".to_owned() + &"00".repeat(31)),
                movement_address_topic(0xcd),
            ],
            movement_word(U256::from(1)),
        );
        let short_erc20_data = movement_word(U256::from(1));
        let short_erc20 = raw_movement_log(
            ERC20_TRANSFER,
            &[movement_address_topic(0xab), movement_address_topic(0xcd)],
            short_erc20_data[..31].to_vec(),
        );
        let short_single = raw_movement_log(
            ERC1155_TRANSFER_SINGLE,
            &indexed,
            movement_word(U256::from(1)),
        );
        let mut invalid_offset_data = batch_data(&[U256::from(1)], &[U256::from(2)]);
        invalid_offset_data[..32].fill(0xff);
        let invalid_offset =
            raw_movement_log(ERC1155_TRANSFER_BATCH, &indexed, invalid_offset_data);
        let mut overlapping_data = batch_data(&[U256::from(1)], &[U256::from(2)]);
        overlapping_data[32..64].copy_from_slice(&movement_word(U256::from(64)));
        let overlapping = raw_movement_log(ERC1155_TRANSFER_BATCH, &indexed, overlapping_data);
        let unequal_lengths = raw_movement_log(
            ERC1155_TRANSFER_BATCH,
            &indexed,
            batch_data(&[U256::from(1)], &[]),
        );
        let oversized = raw_movement_log(
            ERC1155_TRANSFER_BATCH,
            &indexed,
            [
                movement_word(U256::from(64)),
                movement_word(U256::from(96 + 32 * (MAX_ERC1155_BATCH_ITEMS + 1))),
                movement_word(U256::from(MAX_ERC1155_BATCH_ITEMS + 1)),
            ]
            .concat(),
        );
        let mut trailing_data = batch_data(&[U256::from(1)], &[U256::from(2)]);
        trailing_data.extend(movement_word(U256::ZERO));
        let trailing = raw_movement_log(ERC1155_TRANSFER_BATCH, &indexed, trailing_data);
        let invalid_hex = ChainReceiptLog {
            data: "0xgg".to_owned(),
            ..raw_movement_log(
                ERC20_TRANSFER,
                &[movement_address_topic(1), movement_address_topic(2)],
                Vec::new(),
            )
        };
        let malformed = decode_movement_observations(&[
            erc721_shaped,
            bad_padding,
            short_erc20,
            short_single,
            invalid_offset,
            overlapping,
            unequal_lengths,
            oversized,
            trailing,
            invalid_hex,
        ]);
        assert_eq!(malformed.len(), 10);
        assert_eq!(
            malformed[0].status(),
            &MovementObservationStatus::Unsupported(UnsupportedMovementReason::WrongTopicCount)
        );
        assert_eq!(
            malformed[1].status(),
            &MovementObservationStatus::Unsupported(
                UnsupportedMovementReason::IndexedAddressPadding
            )
        );
        assert_eq!(
            malformed[2].status(),
            &MovementObservationStatus::Unsupported(UnsupportedMovementReason::WrongDataLength)
        );
        assert_eq!(
            malformed[3].status(),
            &MovementObservationStatus::Unsupported(UnsupportedMovementReason::WrongDataLength)
        );
        assert_eq!(
            malformed[4].status(),
            &MovementObservationStatus::Unsupported(UnsupportedMovementReason::InvalidBatchOffset)
        );
        assert_eq!(
            malformed[5].status(),
            &MovementObservationStatus::Unsupported(
                UnsupportedMovementReason::NonCanonicalBatchLayout
            )
        );
        assert_eq!(
            malformed[6].status(),
            &MovementObservationStatus::Unsupported(UnsupportedMovementReason::BatchLengthMismatch)
        );
        assert_eq!(
            malformed[7].status(),
            &MovementObservationStatus::Unsupported(UnsupportedMovementReason::BatchTooManyItems)
        );
        assert_eq!(
            malformed[8].status(),
            &MovementObservationStatus::Unsupported(
                UnsupportedMovementReason::BatchDataLengthMismatch
            )
        );
        assert_eq!(
            malformed[9].status(),
            &MovementObservationStatus::Unsupported(UnsupportedMovementReason::InvalidDataHex)
        );
    }

    #[test]
    fn unknown_topics_stay_raw_and_do_not_create_movement_observations() {
        let unknown = raw_movement_log(&format!("0x{}", "55".repeat(32)), &[], Vec::new());
        assert!(decode_movement_observations(&[unknown]).is_empty());
    }

    fn synthetic_proxy_proof(implementation_byte: u8) -> (String, Value) {
        let slot = hex::decode(&PROXY_IMPLEMENTATION_SLOT[2..]).unwrap();
        let slot_key = Nibbles::unpack(B256::from_slice(&Keccak256::digest(slot)));
        let implementation = [implementation_byte; 20];
        let mut storage =
            HashBuilder::default().with_proof_retainer(ProofRetainer::from_iter([slot_key]));
        storage.add_leaf(slot_key, &alloy_rlp::encode(implementation.as_slice()));
        let storage_root = storage.root();
        let storage_proof: Vec<String> = storage
            .take_proof_nodes()
            .into_nodes_sorted()
            .iter()
            .map(|(_, node)| format!("0x{}", hex::encode(node)))
            .collect();
        let account = TrieAccount {
            nonce: 1,
            balance: U256::from(42_u64),
            storage_root,
            code_hash: B256::repeat_byte(0x11),
        };
        let proxy = hex::decode(&EXCHANGES[4][2..]).unwrap();
        let account_key = Nibbles::unpack(B256::from_slice(&Keccak256::digest(proxy)));
        let mut accounts =
            HashBuilder::default().with_proof_retainer(ProofRetainer::from_iter([account_key]));
        accounts.add_leaf(account_key, &alloy_rlp::encode(account));
        let root = format!("{:#x}", accounts.root());
        let account_proof: Vec<String> = accounts
            .take_proof_nodes()
            .into_nodes_sorted()
            .iter()
            .map(|(_, node)| format!("0x{}", hex::encode(node)))
            .collect();
        (
            root,
            json!({
                "address": EXCHANGES[4], "nonce":"0x1", "balance":"0x2a",
                "storageHash":format!("{storage_root:#x}"), "codeHash":format!("{:#x}", account.code_hash),
                "accountProof":account_proof, "storageProof":[{
                    "key":PROXY_IMPLEMENTATION_SLOT,
                    "value":format!("0x{}", hex::encode(implementation)),
                    "proof": storage_proof
                }]
            }),
        )
    }

    #[test]
    fn proxy_state_proof_checks_both_trie_roots_and_exact_slot_value() {
        let (root, proof) = synthetic_proxy_proof(0xab);
        assert_eq!(
            verify_proxy_state_proof(&root, &proof).unwrap(),
            format!("0x{}", "ab".repeat(20))
        );
        let mut altered = proof.clone();
        altered["storageProof"][0]["value"] = json!(format!("0x{}", "cd".repeat(20)));
        assert!(verify_proxy_state_proof(&root, &altered).is_err());
        let mut altered = proof.clone();
        altered["storageProof"][0]["proof"] = json!([]);
        assert!(verify_proxy_state_proof(&root, &altered).is_err());
        let mut altered = proof.clone();
        altered["storageProof"][0]["key"] = json!(format!("0x{}", "22".repeat(32)));
        assert!(verify_proxy_state_proof(&root, &altered).is_err());
        let mut altered = proof.clone();
        altered["balance"] = json!("0x2b");
        assert!(verify_proxy_state_proof(&root, &altered).is_err());
        let mut altered = proof.clone();
        altered["accountProof"][0] = json!("0x80");
        assert!(verify_proxy_state_proof(&root, &altered).is_err());
        assert!(verify_proxy_state_proof(&format!("0x{}", "ff".repeat(32)), &proof).is_err());
    }

    #[derive(Clone)]
    struct StateFixture {
        root: String,
        proof: Value,
        finalized: bool,
        bad_receipts: bool,
    }

    async fn state_rpc(
        State(fixture): State<StateFixture>,
        Json(request): Json<Value>,
    ) -> Json<Value> {
        let result = match request["method"].as_str().unwrap() {
            "eth_chainId" => json!("0x89"),
            "eth_getBlockByNumber" if request["params"][0] == "finalized" => {
                let (number, parent) = if fixture.finalized {
                    (101, format!("0x{}", "66".repeat(32)))
                } else {
                    (99, format!("0x{}", "65".repeat(32)))
                };
                super::header_binding::fixture_header(
                    number,
                    &parent,
                    &fixture.root,
                    &format!("0x{}", "00".repeat(32)),
                    &format!("0x{}", "00".repeat(32)),
                )
            }
            "eth_getBlockByNumber" => {
                let receipts_root = if fixture.bad_receipts {
                    format!("0x{}", "00".repeat(32))
                } else {
                    "0x056b23fbba480696b65fe5a59b8f2148a1299103c4f57df839233af2cf4ca2d2".to_owned()
                };
                let mut header = super::header_binding::fixture_header(
                    100,
                    &format!("0x{}", "88".repeat(32)),
                    &fixture.root,
                    &receipts_root,
                    &format!("0x{}", "00".repeat(32)),
                );
                header["transactions"] = json!([format!("0x{}", "64".repeat(32))]);
                header
            }
            "eth_getLogs" => json!([]),
            "eth_getProof" => fixture.proof,
            "eth_getBlockReceipts" => json!([{
                "transactionIndex":"0x0", "transactionHash":format!("0x{}", "64".repeat(32)),
                "blockNumber":"0x64", "blockHash":super::header_binding::fixture_header(
                    100,
                    &format!("0x{}", "88".repeat(32)),
                    &fixture.root,
                    &if fixture.bad_receipts { format!("0x{}", "00".repeat(32)) }
                    else { "0x056b23fbba480696b65fe5a59b8f2148a1299103c4f57df839233af2cf4ca2d2".to_owned() },
                    &format!("0x{}", "00".repeat(32)),
                )["hash"].clone(),
                "type":"0x0", "status":"0x1", "cumulativeGasUsed":"0x5208",
                "logsBloom":format!("0x{}", "00".repeat(256)), "logs":[]
            }]),
            other => panic!("unexpected RPC: {other}"),
        };
        Json(json!({"jsonrpc":"2.0", "id":1, "result":result}))
    }

    async fn state_provider(fixture: StateFixture) -> String {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let url = format!("http://{}", listener.local_addr().unwrap());
        tokio::spawn(async move {
            axum::serve(
                listener,
                Router::new()
                    .route("/", post(state_rpc))
                    .with_state(fixture),
            )
            .await
            .unwrap();
        });
        url
    }

    fn capture_fifth_native_module_case(
        case: &str,
        fixture: &CtfInventoryFixture,
        observation: &super::FifthNativeBinaryModuleOperationsObservation,
        from_block: u64,
        through_block: u64,
    ) {
        let Ok(directory) = std::env::var("PDH_CAPTURE_FIFTH_NATIVE_MODULE_OPERATIONS_DIRECTORY")
        else {
            return;
        };
        let directory = std::path::PathBuf::from(directory);
        std::fs::create_dir_all(&directory).unwrap();
        let mut unique = BTreeMap::<String, Value>::new();
        for row in fixture.rpc_capture.lock().unwrap().iter() {
            let key = serde_json::to_string(&json!([row["method"], row["params"]])).unwrap();
            if let Some(previous) = unique.get(&key) {
                assert_eq!(previous["result"], row["result"]);
            } else {
                unique.insert(key, row.clone());
            }
        }
        let point_json = |point: &super::FifthNativeBinaryModuleOperationBoundary| {
            let native = point.native_context();
            let selected = native.selected_balances();
            json!({
                "block_number": selected.block_number(),
                "block_hash": selected.block_hash(),
                "state_root": selected.state_root(),
                "owner_position_a": format!("{:#x}", selected.position_balance_a()),
                "owner_position_b": format!("{:#x}", selected.position_balance_b()),
                "owner_pusd": format!("{:#x}", selected.pusd_balance()),
                "module_position_a": format!("{:#x}", point.module_position_balances()[0]),
                "module_position_b": format!("{:#x}", point.module_position_balances()[1]),
                "module_pusd": format!("{:#x}", point.module_pusd_balance()),
                "module_role_bitmap": format!("{:#x}", point.module_role_bitmap()),
                "result_length": format!("{:#x}", native.result_length()),
                "normalized_numerators": native.normalized_numerators().map(|values|
                    values.map(|value| format!("{value:#x}"))),
                "legacy_mapping_value": format!("{:#x}", native.legacy_mapping_value()),
            })
        };
        let locator_json = |locator: &super::fifth_direct_module_operations::FifthDirectModuleTransactionLocator| {
            json!({
                "block_number": locator.block_number(),
                "block_hash": locator.block_hash(),
                "transaction_hash": locator.transaction_hash(),
                "transaction_index": locator.transaction_index(),
            })
        };
        let facts = observation
            .operations()
            .iter()
            .map(|operation| {
                json!({
                    "kind": format!("{:?}", operation.kind()),
                    "condition_id": format!("{:#x}", operation.condition_id()),
                    "position_id": operation.position_id().map(|id| format!("{id:#x}")),
                    "amount": format!("{:#x}", operation.amount()),
                    "payout": operation.payout().map(|value| format!("{value:#x}")),
                    "owner_position_inflows": operation.owner_position_inflows().map(|value| format!("{value:#x}")),
                    "owner_position_outflows": operation.owner_position_outflows().map(|value| format!("{value:#x}")),
                    "owner_pusd_inflow": format!("{:#x}", operation.owner_pusd_inflow()),
                    "owner_pusd_outflow": format!("{:#x}", operation.owner_pusd_outflow()),
                    "funding_transactions": operation.funding_transactions().iter().map(|funding| json!({
                        "transaction": locator_json(funding.transaction()),
                        "asset": format!("{:?}", funding.asset()),
                        "position_id": funding.position_id().map(|id| format!("{id:#x}")),
                        "amount": format!("{:#x}", funding.amount()),
                    })).collect::<Vec<_>>(),
                    "operation_transaction": locator_json(operation.operation_transaction()),
                })
            })
            .collect::<Vec<_>>();
        let status_detail = match observation.status() {
            super::FifthNativeBinaryModuleOperationsStatus::Matched => json!({
                "state": "Matched",
                "block_number": null,
                "transaction_hash": null,
                "reason": null,
            }),
            super::FifthNativeBinaryModuleOperationsStatus::Mismatch {
                block_number,
                holder,
                asset,
                ..
            } => json!({
                "state": "Mismatch",
                "block_number": block_number,
                "transaction_hash": null,
                "reason": format!("{holder:?}:{asset:?}"),
            }),
            super::FifthNativeBinaryModuleOperationsStatus::Unavailable {
                block_number,
                transaction_hash,
                reason,
            } => json!({
                "state": "Unavailable",
                "block_number": block_number,
                "transaction_hash": transaction_hash,
                "reason": format!("{reason:?}"),
            }),
        };
        let payload = json!({
            "provenance": "synthetic rooted loopback fixture",
            "case": case,
            "owner": observation.opening().native_context().selected_balances().owner(),
            "condition_id": format!("{:#x}", observation.opening().native_context().condition_id()),
            "position_ids": observation.opening().native_context().position_ids().map(|id| format!("{id:#x}")),
            "module_proxy": format!("{:#x}", observation.opening().native_context().module_proxy()),
            "module_implementation": format!("{:#x}", observation.opening().native_context().module_implementation()),
            "module_implementation_code_hash": format!("{:#x}", observation.opening().native_context().module_implementation_code_hash()),
            "from_block": from_block,
            "through_block": through_block,
            "expected_parent_hash": observation.evidence().expected_parent_hash(),
            "expected_end_hash": observation.evidence().expected_end_hash(),
            "opening": point_json(observation.opening()),
            "block_observations": observation.block_observations().iter().map(point_json).collect::<Vec<_>>(),
            "status": format!("{:?}", observation.status()),
            "status_detail": status_detail,
            "operations": facts,
            "policy_version": observation.source_policy_version(),
            "actual_request_count": fixture.requests.load(std::sync::atomic::Ordering::Relaxed),
            "rpc_responses": unique.into_values().collect::<Vec<_>>(),
        });
        let path = directory.join(format!("fifth-native-module-{case}-rpc.json"));
        use std::io::Write;
        let mut file = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(path)
            .unwrap();
        file.write_all(serde_json::to_string_pretty(&payload).unwrap().as_bytes())
            .unwrap();
        file.write_all(b"\n").unwrap();
    }

    fn fifth_native_module_operation_fixture(
        case_name: &str,
        cross_block_funding: bool,
        late_unsupported: bool,
    ) -> (CtfInventoryFixture, String, B256, String, String, u64) {
        let vectors: Value = serde_json::from_str(include_str!(
            "chain_log_audit/artifacts/fifth-native-module-source-vectors.json"
        ))
        .unwrap();
        let owner = vectors["owner"].as_str().unwrap().to_owned();
        let module = vectors["module"].as_str().unwrap();
        let condition = parse_fixed_b256(vectors["condition_id"].as_str().unwrap()).unwrap();
        let case = vectors["cases"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["name"] == case_name)
            .unwrap();
        let calls = vectors["calls"].as_array().unwrap();
        let call = |name: &Value| {
            calls
                .iter()
                .find(|row| row["name"].as_str() == name.as_str())
                .unwrap()
        };
        let source_call_names = case["calls"].as_array().unwrap();
        let source_logs = case["source_receipt_logs"].as_array().unwrap();
        assert_eq!(source_call_names.len(), source_logs.len());
        let signed_calls = source_call_names
            .iter()
            .enumerate()
            .map(|(nonce, name)| {
                let source = call(name);
                let data = hex::decode(
                    source["calldata"]
                        .as_str()
                        .unwrap()
                        .trim_start_matches("0x"),
                )
                .unwrap();
                let (transaction, recovered) = signed_polygon_owner_call(
                    source["to"].as_str().unwrap(),
                    &data,
                    u64::try_from(nonce).unwrap(),
                );
                assert_eq!(recovered, owner);
                (transaction, source_logs[nonce].as_array().unwrap().to_vec())
            })
            .collect::<Vec<_>>();
        let (opening_positions, opening_cash, closing_positions, closing_cash) = {
            let opening = case["opening_owner"].as_array().unwrap();
            let closing = case["closing_owner"].as_array().unwrap();
            let value = |row: &[Value], index: usize| U256::from(row[index].as_u64().unwrap());
            (
                [value(opening, 0), value(opening, 1)],
                value(opening, 2),
                [value(closing, 0), value(closing, 1)],
                value(closing, 2),
            )
        };
        let result_values = case["result_slots"].as_array().unwrap();
        let result = [
            U256::from(result_values[0].as_u64().unwrap()),
            U256::from(result_values[1].as_u64().unwrap()),
            U256::from(result_values[2].as_u64().unwrap()),
        ];

        let mut fixture = ctf_inventory_fixture(U256::ZERO, 0);
        fixture.finalized_block = 102;
        fixture.filter_fifth_code_proofs_by_requested_keys = true;
        let (opening_root, opening_proofs) =
            fifth_legacy_binary_balances::test_rooted_native_module_operation_point_packet(
                &owner,
                condition,
                opening_positions,
                opening_cash,
                [U256::ZERO; 2],
                U256::ZERO,
                U256::ONE,
                result,
            );
        fixture.state_root = opening_root;

        let mut proofs_by_block = BTreeMap::from([(99, opening_proofs)]);
        if cross_block_funding {
            assert_eq!(case_name, "split");
            let (middle_root, middle_proofs) =
                fifth_legacy_binary_balances::test_rooted_native_module_operation_point_packet(
                    &owner,
                    condition,
                    [U256::ZERO; 2],
                    U256::ZERO,
                    [U256::ZERO; 2],
                    U256::from(10),
                    U256::ONE,
                    result,
                );
            proofs_by_block.insert(100, middle_proofs);
            let (end_root, end_proofs) =
                fifth_legacy_binary_balances::test_rooted_native_module_operation_point_packet(
                    &owner,
                    condition,
                    closing_positions,
                    closing_cash,
                    [U256::ZERO; 2],
                    U256::ZERO,
                    U256::ONE,
                    result,
                );
            fixture.post_state = Some((middle_root, Value::Null));
            fixture.extra_post_state = Some((end_root, Value::Null));
            proofs_by_block.insert(101, end_proofs);
        } else {
            let (end_root, end_proofs) =
                fifth_legacy_binary_balances::test_rooted_native_module_operation_point_packet(
                    &owner,
                    condition,
                    closing_positions,
                    closing_cash,
                    [U256::ZERO; 2],
                    U256::ZERO,
                    U256::ONE,
                    result,
                );
            fixture.post_state = Some((end_root.clone(), Value::Null));
            proofs_by_block.insert(100, end_proofs.clone());
            if late_unsupported {
                fixture.extra_post_state = Some((end_root, Value::Null));
                proofs_by_block.insert(101, end_proofs);
            }
        }
        fixture.fifth_code_proofs_by_block = Some(proofs_by_block);

        let split_call_at_block_101 = cross_block_funding;
        let split_prefix_len = usize::from(split_call_at_block_101);
        let (block_100_calls, block_101_calls) = if split_call_at_block_101 {
            (
                &signed_calls[..split_prefix_len],
                &signed_calls[split_prefix_len..],
            )
        } else {
            (&signed_calls[..], &signed_calls[..0])
        };
        fixture.rooted_gas_block = Some(RootedGasBlockFixture {
            transactions: block_100_calls
                .iter()
                .map(|(transaction, _)| transaction.clone())
                .collect(),
            receipt_logs: block_100_calls
                .iter()
                .map(|(_, logs)| logs.clone())
                .collect(),
            receipt_statuses: vec![1; block_100_calls.len()],
            cumulative_gas_used: (1..=block_100_calls.len())
                .map(|index| u64::try_from(index).unwrap() * 21_000)
                .collect(),
            receipt_types: vec![0; block_100_calls.len()],
            gas_limit: 1_000_000,
            base_fee_per_gas: U256::ZERO,
            header_gas_used_override: None,
            tamper_header_gas_used: false,
            tamper_cumulative_index: None,
        });
        if !block_101_calls.is_empty() {
            assert_eq!(block_101_calls.len(), 1);
            fixture.extra_direct_call_transaction = Some(block_101_calls[0].0.clone());
            fixture.extra_inventory_logs = Some(block_101_calls[0].1.clone());
        }
        let through_block = if cross_block_funding || late_unsupported {
            101
        } else {
            100
        };
        if late_unsupported {
            let (transaction, recovered) =
                signed_polygon_owner_call(module, &[0xde, 0xad, 0xbe, 0xef], 2);
            assert_eq!(recovered, owner);
            fixture.extra_direct_call_transaction = Some(transaction);
            fixture.extra_inventory_logs = Some(Vec::new());
        }
        let (opening_header, closing_header, block101, _) =
            ctf_inventory_headers_with_102(&fixture);
        let end_hash = if through_block == 100 {
            closing_header["hash"].as_str().unwrap()
        } else {
            block101["hash"].as_str().unwrap()
        }
        .to_owned();
        (
            fixture,
            owner,
            condition,
            opening_header["hash"].as_str().unwrap().to_owned(),
            end_hash,
            through_block,
        )
    }

    async fn verify_fifth_native_module_fixture(
        fixture: &CtfInventoryFixture,
        owner: &str,
        condition: B256,
        through_block: u64,
        budget: usize,
    ) -> Result<
        super::FifthNativeBinaryModuleOperationsObservation,
        super::BoundedFifthNativeBinaryModuleOperationsError,
    > {
        let (opening, closing, block101, _) = ctf_inventory_headers_with_102(fixture);
        let end_hash = if through_block == 100 {
            closing["hash"].as_str().unwrap()
        } else {
            block101["hash"].as_str().unwrap()
        };
        let (primary, primary_task) = serve_direct_module_fixture(fixture.clone()).await;
        let (secondary, secondary_task) = serve_direct_module_fixture(fixture.clone()).await;
        let result = ChainLogVerifier::new(&primary, &secondary)
            .unwrap()
            .verify_fifth_native_binary_module_operations_interval_bounded(
                owner,
                &format!("{condition:#x}"),
                100,
                through_block,
                opening["hash"].as_str().unwrap(),
                end_hash,
                budget,
                Duration::from_secs(10),
            )
            .await;
        primary_task.abort();
        secondary_task.abort();
        result
    }

    #[tokio::test]
    async fn proxy_state_proof_requires_finalized_matching_proofs_from_both_providers() {
        let (root, proof) = synthetic_proxy_proof(0xab);
        let good = StateFixture {
            root,
            proof,
            finalized: true,
            bad_receipts: false,
        };
        let first = state_provider(good.clone()).await;
        let second = state_provider(good.clone()).await;
        let verifier = ChainLogVerifier::new(&first, &second).unwrap();
        let result = verifier
            .verify_proxy_implementation_block(100)
            .await
            .unwrap();
        assert_eq!(result.implementation, format!("0x{}", "ab".repeat(20)));
        assert_eq!(result.state_root, good.root);
        let proof = verifier
            .verify_proxy_implementation_proof(100)
            .await
            .unwrap();
        let stored: ChainProxyImplementationProof =
            serde_json::from_value(serde_json::to_value(&proof).unwrap()).unwrap();
        stored.revalidate().unwrap();
        let mut tampered = stored.clone();
        tampered.secondary_proof["storageProof"][0]["value"] = json!("0x0");
        assert_eq!(tampered.revalidate(), Err(ChainLogAuditError::Unverified));
        let trace = verifier.verify_proxy_version_trace(100, 100).await.unwrap();
        assert_eq!(trace.evidence.blocks.len(), 1);
        assert!(trace.upgrades_after_anchor.is_empty());
        assert_eq!(trace.event_implied_implementation, result.implementation);
        assert_eq!(
            verifier.verify_proxy_version_trace(100, 164).await,
            Err(ChainLogAuditError::InvalidInput)
        );
        let bad_root = state_provider(StateFixture {
            bad_receipts: true,
            ..good.clone()
        })
        .await;
        assert_eq!(
            ChainLogVerifier::new(&first, &bad_root)
                .unwrap()
                .verify_proxy_version_trace(100, 100)
                .await,
            Err(ChainLogAuditError::Divergent)
        );
        let mut bad = good.clone();
        bad.proof["storageProof"][0]["value"] = json!("0x0");
        let bad_provider = state_provider(bad).await;
        assert_eq!(
            ChainLogVerifier::new(&first, &bad_provider)
                .unwrap()
                .verify_proxy_implementation_block(100)
                .await,
            Err(ChainLogAuditError::Unverified)
        );
        let (root, proof) = synthetic_proxy_proof(0xcd);
        let divergent = state_provider(StateFixture {
            root,
            proof,
            finalized: true,
            bad_receipts: false,
        })
        .await;
        assert_eq!(
            ChainLogVerifier::new(&first, &divergent)
                .unwrap()
                .verify_proxy_implementation_block(100)
                .await,
            Err(ChainLogAuditError::Divergent)
        );
        let stale = state_provider(StateFixture {
            finalized: false,
            ..good
        })
        .await;
        assert_eq!(
            ChainLogVerifier::new(&first, &stale)
                .unwrap()
                .verify_proxy_implementation_block(100)
                .await,
            Err(ChainLogAuditError::Unverified)
        );
    }

    #[test]
    fn proxy_version_trace_refuses_holes_and_conflicting_anchor_events() {
        let hash = |byte: &str| format!("0x{}", byte.repeat(32));
        let anchor = ChainProxyImplementationEvidence {
            block_number: 100,
            block_hash: hash("11"),
            state_root: hash("22"),
            implementation: format!("0x{}", "ab".repeat(20)),
        };
        let block = |number: u64, parent: &str, current: &str| ChainReceiptEvidence {
            logs: ChainLogEvidence {
                from_block: number,
                through_block: number,
                canonical_parent_hash: hash(parent),
                canonical_start_hash: hash(current),
                canonical_end_hash: hash(current),
                filled_logs: 0,
                sha256: "00".repeat(32),
            },
            verified_receipts_root: hash("33"),
            receipt_count: 1,
        };
        let window = ChainReceiptWindowEvidence {
            from_block: 100,
            through_block: 101,
            blocks: vec![block(100, "88", "11"), block(101, "11", "44")],
        };
        let anchor_event = ProxyUpgradeEvent {
            block_number: 100,
            log_index: 0,
            implementation: anchor.implementation.clone(),
        };
        let next_event = ProxyUpgradeEvent {
            block_number: 101,
            log_index: 0,
            implementation: format!("0x{}", "cd".repeat(20)),
        };
        let trace = proxy_version_trace(
            anchor.clone(),
            window.clone(),
            vec![anchor_event.clone(), next_event.clone()],
        )
        .unwrap();
        assert_eq!(
            trace.event_implied_implementation,
            next_event.implementation
        );
        assert_eq!(trace.upgrades_after_anchor, vec![next_event]);
        let chunk = ChainReceiptWindowEvidence {
            from_block: 101,
            through_block: 102,
            blocks: vec![block(101, "11", "44"), block(102, "44", "55")],
        };
        let later = ProxyUpgradeEvent {
            block_number: 102,
            log_index: 0,
            implementation: format!("0x{}", "ee".repeat(20)),
        };
        let continued =
            extend_proxy_version_trace(&trace, chunk.clone(), vec![later.clone()]).unwrap();
        assert_eq!(continued.evidence.blocks.len(), 3);
        assert_eq!(continued.event_implied_implementation, later.implementation);
        assert_eq!(continued.upgrades_after_anchor.len(), 2);
        assert_eq!(
            trace.evidence.through_block, 101,
            "a failed or successful extension cannot mutate the prior trace"
        );
        let mut wrong_overlap = chunk.clone();
        wrong_overlap.blocks[0].verified_receipts_root = hash("99");
        assert_eq!(
            extend_proxy_version_trace(&trace, wrong_overlap, vec![]),
            Err(ChainLogAuditError::Divergent)
        );
        let mut hole = chunk.clone();
        hole.blocks[1].logs.from_block = 103;
        hole.blocks[1].logs.through_block = 103;
        assert_eq!(
            extend_proxy_version_trace(&trace, hole, vec![]),
            Err(ChainLogAuditError::Divergent)
        );
        let mut conflicting_overlap = later.clone();
        conflicting_overlap.block_number = 101;
        assert_eq!(
            extend_proxy_version_trace(&trace, chunk, vec![conflicting_overlap]),
            Err(ChainLogAuditError::Divergent)
        );
        assert_eq!(
            proxy_version_trace(anchor.clone(), window.clone(), vec![])
                .unwrap()
                .event_implied_implementation,
            anchor.implementation
        );
        let mut conflicting = anchor_event.clone();
        conflicting.implementation = format!("0x{}", "ee".repeat(20));
        assert_eq!(
            proxy_version_trace(anchor.clone(), window.clone(), vec![conflicting]),
            Err(ChainLogAuditError::Divergent)
        );
        let mut broken = window.clone();
        broken.blocks[1].logs.canonical_parent_hash = hash("99");
        assert_eq!(
            proxy_version_trace(anchor.clone(), broken, vec![]),
            Err(ChainLogAuditError::Divergent)
        );
        let mut incomplete = window.clone();
        incomplete.blocks.pop();
        assert_eq!(
            proxy_version_trace(anchor.clone(), incomplete, vec![]),
            Err(ChainLogAuditError::Divergent)
        );
        let mut mismatched = anchor.clone();
        mismatched.block_hash = hash("aa");
        assert_eq!(
            proxy_version_trace(mismatched, window.clone(), vec![]),
            Err(ChainLogAuditError::Divergent)
        );
        assert_eq!(
            proxy_version_trace(anchor, window, vec![anchor_event.clone(), anchor_event]),
            Err(ChainLogAuditError::Divergent)
        );
    }

    #[test]
    fn proxy_upgrade_parser_accepts_only_padded_indexed_events_at_the_fifth_proxy() {
        let signature = format!("0x{}", hex::encode(Keccak256::digest(b"Upgraded(address)")));
        let implementation = format!("0x{}", "ab".repeat(20));
        let log = json!({
            "address": EXCHANGES[4], "topics": [signature, format!("0x{}{}", "00".repeat(12), "ab".repeat(20))],
            "data": "0x", "blockNumber": "0x64", "logIndex": "0x7"
        });
        let receipt = json!({"logs": [log.clone()]});
        let expected = vec![ProxyUpgradeEvent {
            block_number: 100,
            log_index: 7,
            implementation,
        }];
        assert_eq!(proxy_upgrade_events(&[receipt]).unwrap(), expected);
        let mut uppercase = log.clone();
        uppercase["topics"][0] = json!(signature.to_ascii_uppercase().replacen("0X", "0x", 1));
        assert_eq!(
            proxy_upgrade_events(&[json!({"logs": [uppercase]})]).unwrap(),
            expected
        );
        let mut bad = log.clone();
        bad["topics"][1] = json!(format!("0x{}", "ab".repeat(32)));
        assert!(proxy_upgrade_events(&[json!({"logs": [bad]})]).is_err());
        let mut bad = log.clone();
        bad["data"] = json!("0x00");
        assert!(proxy_upgrade_events(&[json!({"logs": [bad]})]).is_err());
        let mut other_venue = log;
        other_venue["address"] = json!(EXCHANGES[2]);
        assert!(
            proxy_upgrade_events(&[json!({"logs": [other_venue]})])
                .unwrap()
                .is_empty()
        );
    }

