    #[test]
    fn transaction_encoder_rejects_unsupported_and_malformed_signed_fields() {
        let mut transaction = published_eip155_legacy_transaction();
        transaction.as_object_mut().unwrap().remove("v");
        assert!(encode_signed_transaction(&transaction).is_err());

        let typed = published_eip2930_transaction();
        for kind in ["0x3", "0x4", "0x5", "0x7f"] {
            let mut unsupported = typed.clone();
            unsupported["type"] = json!(kind);
            assert!(encode_signed_transaction(&unsupported).is_err());
        }
        let mut conflict = published_eip2930_transaction();
        conflict["v"] = json!("0x1");
        assert!(encode_signed_transaction(&conflict).is_err());
        let mut data_conflict = published_eip155_legacy_transaction();
        data_conflict["data"] = json!("0x01");
        assert!(encode_signed_transaction(&data_conflict).is_err());
        let mut missing_to = published_eip155_legacy_transaction();
        missing_to.as_object_mut().unwrap().remove("to");
        assert!(encode_signed_transaction(&missing_to).is_err());
        let mut bad_access = published_eip2930_transaction();
        bad_access["accessList"][0]["storageKeys"] = json!(["0x01"]);
        assert!(encode_signed_transaction(&bad_access).is_err());
        let mut bad_parity = published_eip2930_transaction();
        bad_parity["yParity"] = json!("0x2");
        assert!(encode_signed_transaction(&bad_parity).is_err());
        let mut missing_chain = published_eip2930_transaction();
        missing_chain.as_object_mut().unwrap().remove("chainId");
        assert!(encode_signed_transaction(&missing_chain).is_err());
        let mut missing_parity = published_eip2930_transaction();
        missing_parity.as_object_mut().unwrap().remove("yParity");
        assert!(encode_signed_transaction(&missing_parity).is_err());
        let mut malformed_quantity = published_eip2930_transaction();
        malformed_quantity["nonce"] = json!("0xz");
        assert!(encode_signed_transaction(&malformed_quantity).is_err());
        let mut unsupported_metadata = published_eip1559_transaction();
        unsupported_metadata["blobVersionedHashes"] = json!([]);
        assert!(encode_signed_transaction(&unsupported_metadata).is_err());
        let mut explicit_creation = published_eip155_legacy_transaction();
        explicit_creation["to"] = Value::Null;
        assert!(encode_signed_transaction(&explicit_creation).is_ok());
    }

