    fn install_condition_state_roots_for_owner(
        fixture: &mut CtfInventoryFixture,
        identity: &ctf_position_identity::DerivedRootBinaryIdentity,
        owner: Address,
        states: [[U256; 4]; 3],
        balances: [[U256; 3]; 3],
    ) {
        let selected_index = usize::from(identity.selected_index_set == 2);
        let selected_token =
            CtfTokenId(U256::from_be_bytes(identity.position_ids[selected_index].0));
        let snapshots = states
            .into_iter()
            .zip(balances)
            .map(|(state, [first, second, cash])| {
                synthetic_paired_condition_state(
                    owner,
                    selected_token,
                    [first, second][selected_index],
                    [first, second][1 - selected_index],
                    cash,
                    identity,
                    state,
                )
            })
            .collect::<Vec<_>>();
        let mut snapshots = snapshots;
        let opening = snapshots.remove(0);
        let prepared = snapshots.remove(0);
        let resolved = snapshots.remove(0);
        fixture.state_root = opening.0;
        fixture.proof = opening.1;
        fixture.opening_condition_proof = Some(opening.2);
        fixture.opening_complementary_proof = Some(opening.3);
        fixture.opening_usdc_proofs = Some((opening.4, opening.5));
        fixture.opening_exchange_proof = Some(opening.6);
        fixture.post_state = Some((prepared.0, prepared.1));
        fixture.post_condition_proof = Some(prepared.2);
        fixture.post_complementary_proof = Some(prepared.3);
        fixture.post_usdc_proofs = Some((prepared.4, prepared.5));
        fixture.post_exchange_proof = Some(prepared.6);
        fixture.extra_post_state = Some((resolved.0, resolved.1));
        fixture.extra_condition_proof = Some(resolved.2);
        fixture.extra_complementary_proof = Some(resolved.3);
        fixture.extra_post_usdc_proofs = Some((resolved.4, resolved.5));
        fixture.extra_post_exchange_proof = Some(resolved.6);
        fixture.inventory_logs = Some(Vec::new());
        fixture.extra_inventory_logs = Some(Vec::new());
    }

