    #[allow(clippy::too_many_arguments)]
    fn test_match_orders_case(
        active_maker: &str,
        active_side: V1DirectFillSide,
        active_maker_amount: U256,
        active_taker_amount: U256,
        active_fill: U256,
        active_fee_rate: U256,
        passive_maker: &str,
        passive_maker_amount: U256,
        passive_taker_amount: U256,
        passive_fill: U256,
        passive_fee_rate: U256,
        operator_key: u8,
    ) -> (Value, Vec<ChainReceiptLog>, String) {
        let token_id = test_token_id().value();
        let passive_side = match active_side {
            V1DirectFillSide::Buy => V1DirectFillSide::Sell,
            V1DirectFillSide::Sell => V1DirectFillSide::Buy,
        };
        let active_order = test_v1_fill_order_input(
            active_maker,
            token_id,
            active_maker_amount,
            active_taker_amount,
            active_fee_rate,
            active_side,
            active_fill,
        );
        let passive_order = test_v1_fill_order_input(
            passive_maker,
            token_id,
            passive_maker_amount,
            passive_taker_amount,
            passive_fee_rate,
            passive_side,
            passive_fill,
        );
        let input =
            test_v1_match_orders_input(&active_order, &passive_order, active_fill, passive_fill);
        let call = decode_v1_match_orders_call(&input).unwrap();
        let active = &call.taker_order;
        let passive = &call.maker_orders[0];
        let active_taking =
            checked_mul_div(active_fill, active.taker_amount, active.maker_amount).unwrap();
        let passive_taking =
            checked_mul_div(passive_fill, passive.taker_amount, passive.maker_amount).unwrap();
        let active_fee = calculate_v1_match_order_fee(
            active,
            active_fill,
            active_taking,
            V1MatchFeePrice::ActualFill,
        )
        .unwrap();
        let passive_fee = calculate_v1_match_order_fee(
            passive,
            passive_fill,
            passive_taking,
            V1MatchFeePrice::SignedOrder,
        )
        .unwrap();
        let active_net = active_taking - active_fee;
        let passive_net = passive_taking - passive_fee;
        let (active_maker_asset, active_taker_asset) = order_asset_ids(active);
        let (passive_maker_asset, passive_taker_asset) = order_asset_ids(passive);
        let active_hash = v1_order_hash(active).unwrap();
        let passive_hash = v1_order_hash(passive).unwrap();
        let (transaction, operator) = signed_polygon_transaction_with_key_and_gas_price(
            EXCHANGES[0],
            &input,
            operator_key,
            U256::from(30),
        );
        let transfer = |asset_id: U256, from: &str, to: &str, amount: U256, index: u64| {
            if asset_id.is_zero() {
                test_erc20_transfer(from, to, amount, index)
            } else {
                test_transfer_single(from, to, asset_id, amount, index)
            }
        };
        let mut logs = vec![
            transfer(
                active_maker_asset,
                &active.maker,
                EXCHANGES[0],
                active_fill,
                0,
            ),
            transfer(
                passive_maker_asset,
                &passive.maker,
                EXCHANGES[0],
                passive_fill,
                1,
            ),
            transfer(
                passive_taker_asset,
                EXCHANGES[0],
                &passive.maker,
                passive_net,
                2,
            ),
        ];
        if !passive_fee.is_zero() {
            logs.push(transfer(
                passive_taker_asset,
                EXCHANGES[0],
                &operator,
                passive_fee,
                logs.len() as u64,
            ));
            logs.push(test_fee_charged_log(
                &operator,
                passive_taker_asset,
                passive_fee,
                logs.len() as u64,
            ));
        }
        logs.push(test_order_filled_log(
            &passive_hash,
            &passive.maker,
            &active.maker,
            passive_maker_asset,
            passive_taker_asset,
            passive_fill,
            passive_taking,
            passive_fee,
            logs.len() as u64,
        ));
        logs.push(transfer(
            active_taker_asset,
            EXCHANGES[0],
            &active.maker,
            active_net,
            logs.len() as u64,
        ));
        if !active_fee.is_zero() {
            logs.push(transfer(
                active_taker_asset,
                EXCHANGES[0],
                &operator,
                active_fee,
                logs.len() as u64,
            ));
            logs.push(test_fee_charged_log(
                &operator,
                active_taker_asset,
                active_fee,
                logs.len() as u64,
            ));
        }
        logs.push(test_order_filled_log(
            &active_hash,
            &active.maker,
            EXCHANGES[0],
            active_maker_asset,
            active_taker_asset,
            active_fill,
            active_taking,
            active_fee,
            logs.len() as u64,
        ));
        let mut matched_data = Vec::new();
        matched_data.extend(movement_word(active_maker_asset));
        matched_data.extend(movement_word(active_taker_asset));
        matched_data.extend(movement_word(active_fill));
        matched_data.extend(movement_word(active_taking));
        logs.push(test_indexed_event_log(
            EXCHANGES[0],
            &v1_event_topic("OrdersMatched(bytes32,address,uint256,uint256,uint256,uint256)"),
            &[active_hash, test_address_topic(&active.maker)],
            matched_data,
            logs.len() as u64,
        ));
        (transaction, logs, operator)
    }

    fn test_log_rows(logs: Vec<ChainReceiptLog>) -> Vec<Value> {
        logs.into_iter()
            .map(|log| json!({"address":log.address, "topics":log.topics, "data":log.data}))
            .collect()
    }

