    fn synthetic_paired_asset_state(
        owner: Address,
        token_id: CtfTokenId,
        ctf_balance: Option<U256>,
        usdc_e_balance: U256,
    ) -> (String, Value, Value, Value, Value) {
        let (_, mut ctf_proof, _) = synthetic_ctf_balance_proof(
            owner,
            token_id,
            ctf_balance,
            ctf_balance.is_none(),
            B256::new(CTF_CONDITIONAL_TOKENS_CODE_HASH_CANDIDATE),
        );
        let (_, mut proxy_proof, mut implementation_proof) = synthetic_usdc_e_proofs(
            owner,
            usdc_e_balance,
            U256::from(USDC_E_EXPECTED_DECIMALS),
            test_usdc_e_implementation_word(),
            usdc_e_code_hash(USDC_E_PROXY_CODE_HASH_CANDIDATE),
            usdc_e_code_hash(USDC_E_IMPLEMENTATION_CODE_HASH_CANDIDATE),
        );
        let mut exchange_proof = synthetic_v1_exchange_account_proof();
        let state_root = combine_paired_account_proofs(
            &mut ctf_proof,
            &mut proxy_proof,
            &mut implementation_proof,
            &mut exchange_proof,
        );
        (
            state_root,
            ctf_proof,
            proxy_proof,
            implementation_proof,
            exchange_proof,
        )
    }

