        fixture.opening_usdc_proofs = Some((opening_proxy, opening_implementation));
        fixture.opening_exchange_proof = Some(opening_exchange);
        fixture.post_state = Some((closing_root, closing_ctf));
        fixture.post_usdc_proofs = Some((closing_proxy, closing_implementation));
        fixture.post_exchange_proof = Some(closing_exchange);
        fixture.inventory_logs = Some(Vec::new());
