    #[tokio::test]
    async fn complementary_inventory_refuses_proof_tampering_and_keeps_replay_mismatch_explicit() {
        let condition_id = B256::ZERO;
        let (mut fixture, token_id) = ctf_root_binary_identity_fixture(condition_id, 1);
        let identity = ctf_position_identity::derive_root_binary_identity_bounded(
            condition_id,
            token_id.value(),
            tokio::time::Instant::now() + Duration::from_secs(10),
        )
        .await
        .unwrap();
        install_condition_state_roots(
            &mut fixture,
            &identity,
            [
                [U256::ZERO; 4],
                [U256::from(2), U256::ZERO, U256::ZERO, U256::ZERO],
                [U256::from(2), U256::from(4), U256::from(1), U256::from(3)],
            ],
        );
        assert!(matches!(
            verify_complementary_root_fixture(
                &fixture,
                token_id,
                condition_id,
                155,
                Duration::from_secs(10),
            )
            .await,
            Err(BoundedV1TradeAttributionError::RequestBudgetExceeded)
        ));
        let mut wrong_key = fixture.clone();
        wrong_key.opening_complementary_proof.as_mut().unwrap()["storageProof"][0]["key"] =
            json!(format!("0x{}", "ee".repeat(32)));
        let mut wrong_value = fixture.clone();
        wrong_value.opening_complementary_proof.as_mut().unwrap()["storageProof"][0]["value"] =
            json!("0x4e");
        let mut wrong_code = fixture.clone();
        wrong_code.opening_complementary_proof.as_mut().unwrap()["codeHash"] =
            json!(format!("0x{}", "ee".repeat(32)));
        let mut extra_entry = fixture.clone();
        let entry =
            extra_entry.opening_complementary_proof.as_ref().unwrap()["storageProof"][0].clone();
        extra_entry.opening_complementary_proof.as_mut().unwrap()["storageProof"] =
            json!([entry.clone(), entry]);
        let mut bad_account_path = fixture.clone();
        bad_account_path
            .opening_complementary_proof
            .as_mut()
            .unwrap()["accountProof"][0] = json!(format!("0x{}", "00".repeat(32)));
        for tampered in [
            wrong_key,
            wrong_value,
            wrong_code,
            extra_entry,
            bad_account_path,
        ] {
            assert!(
                verify_complementary_root_fixture(
                    &tampered,
                    token_id,
                    condition_id,
                    1200,
                    Duration::from_secs(10)
                )
                .await
                .is_err()
            );
        }

        let mut divergent_primary = fixture.clone();
        divergent_primary
            .opening_complementary_proof
            .as_mut()
            .unwrap()["storageProof"][0]["value"] = json!("0x4e");
        let (opening, closing, quiet, _) = ctf_inventory_headers_with_102(&fixture);
        let intervals = intervals_from_headers(&opening, &closing, &quiet);
        let primary = ctf_inventory_provider(divergent_primary).await;
        let secondary = ctf_inventory_provider(fixture.clone()).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        assert!(
            verifier
                .verify_v1_trade_attribution_intervals_with_complementary_inventory_bounded(
                    &format!("{:#x}", test_owner()),
                    token_id,
                    condition_id.0,
                    &intervals,
                    1200,
                    Duration::from_secs(10),
                )
                .await
                .is_err()
        );

        let token0 = U256::from_be_bytes(identity.position_ids[0].0);
        let token1 = U256::from_be_bytes(identity.position_ids[1].0);
        let mut mismatch = fixture.clone();
        install_condition_state_roots_with_balances(
            &mut mismatch,
            &identity,
            [
                [U256::ZERO; 4],
                [U256::from(2), U256::ZERO, U256::ZERO, U256::ZERO],
                [U256::from(2), U256::from(4), U256::from(1), U256::from(3)],
            ],
            [
                [U256::from(55), U256::from(77), U256::from(1000)],
                [U256::from(55), U256::from(76), U256::from(1000)],
                [U256::from(55), U256::from(76), U256::from(1000)],
            ],
        );
        mismatch.inventory_logs = Some(vec![json!({"address":CTF_CONDITIONAL_TOKENS_ADDRESS,
            "topics":ctf_raw_single(0x11,0x33,token1,U256::from(2)).topics,
            "data":ctf_raw_single(0x11,0x33,token1,U256::from(2)).data})]);
        mismatch.extra_inventory_logs = Some(Vec::new());
        let reports = verify_complementary_root_fixture(
            &mismatch,
            token_id,
            condition_id,
            1200,
            Duration::from_secs(10),
        )
        .await
        .unwrap();
        assert!(
            matches!(reports[0].complementary_inventory().unwrap().statuses()[1],
            PairedInventoryAssetStatus::Mismatch { block_number: 100, authenticated_balance, reconstructed_balance }
                if authenticated_balance == U256::from(76) && reconstructed_balance == U256::from(75))
        );

        let mut malformed = fixture;
        let malformed_log = ctf_raw_batch(0x11, 0x33, &[token0, token1], &[U256::from(1)]);
        malformed.inventory_logs = Some(vec![json!({"address":malformed_log.address,
            "topics":malformed_log.topics,"data":malformed_log.data})]);
        malformed.extra_inventory_logs = Some(Vec::new());
        let reports = verify_complementary_root_fixture(
            &malformed,
            token_id,
            condition_id,
            1200,
            Duration::from_secs(10),
        )
        .await
        .unwrap();
        assert!(
            reports[0]
                .complementary_inventory()
                .unwrap()
                .statuses()
                .iter()
                .any(|status| matches!(status, PairedInventoryAssetStatus::Unavailable { .. }))
        );
    }

    #[tokio::test]
    async fn complementary_inventory_replay_and_transaction_totals_fail_closed_on_overflow() {
        let condition_id = B256::ZERO;
        let (base, token_id) = ctf_root_binary_identity_fixture(condition_id, 1);
        let identity = ctf_position_identity::derive_root_binary_identity_bounded(
            condition_id,
            token_id.value(),
            tokio::time::Instant::now() + Duration::from_secs(10),
        )
        .await
        .unwrap();
        let token1 = U256::from_be_bytes(identity.position_ids[1].0);

        let mut inbound_overflow = base.clone();
        install_condition_state_roots_with_balances(
            &mut inbound_overflow,
            &identity,
            [
                [U256::ZERO; 4],
                [U256::from(2), U256::ZERO, U256::ZERO, U256::ZERO],
                [U256::from(2), U256::from(4), U256::ONE, U256::from(3)],
            ],
            [
                [U256::from(55), U256::MAX, U256::from(1000)],
                [U256::from(55), U256::ZERO, U256::from(1000)],
                [U256::from(55), U256::ZERO, U256::from(1000)],
            ],
        );
        let incoming = ctf_raw_single(0x22, 0x11, token1, U256::ONE);
        inbound_overflow.inventory_logs = Some(vec![json!({
            "address":incoming.address,"topics":incoming.topics,"data":incoming.data
        })]);
        inbound_overflow.extra_inventory_logs = Some(Vec::new());
        let reports = verify_complementary_root_fixture(
            &inbound_overflow,
            token_id,
            condition_id,
            1200,
            Duration::from_secs(10),
        )
        .await
        .unwrap();
        assert!(matches!(
            reports[0].complementary_inventory().unwrap().statuses()[1],
            PairedInventoryAssetStatus::Unavailable { .. }
        ));

        let mut outbound_underflow = base.clone();
        install_condition_state_roots_with_balances(
            &mut outbound_underflow,
            &identity,
            [
                [U256::ZERO; 4],
                [U256::from(2), U256::ZERO, U256::ZERO, U256::ZERO],
                [U256::from(2), U256::from(4), U256::from(1), U256::from(3)],
            ],
            [
                [U256::from(55), U256::ZERO, U256::from(1000)],
                [U256::from(55), U256::MAX, U256::from(1000)],
                [U256::from(55), U256::MAX, U256::from(1000)],
            ],
        );
        let outgoing = ctf_raw_single(0x11, 0x22, token1, U256::ONE);
        outbound_underflow.inventory_logs = Some(vec![json!({
            "address":outgoing.address,"topics":outgoing.topics,"data":outgoing.data
        })]);
        outbound_underflow.extra_inventory_logs = Some(Vec::new());
        let reports = verify_complementary_root_fixture(
            &outbound_underflow,
            token_id,
            condition_id,
            1200,
            Duration::from_secs(10),
        )
        .await
        .unwrap();
        assert!(matches!(
            reports[0].complementary_inventory().unwrap().statuses()[1],
            PairedInventoryAssetStatus::Unavailable { .. }
        ));

        let mut transaction_total_overflow = base;
        install_condition_state_roots_with_balances(
            &mut transaction_total_overflow,
            &identity,
            [
                [U256::ZERO; 4],
                [U256::from(2), U256::ZERO, U256::ZERO, U256::ZERO],
                [U256::from(2), U256::from(4), U256::MAX, U256::ZERO],
            ],
            [
                [U256::from(55), U256::ZERO, U256::from(1000)],
                [U256::from(55), U256::MAX, U256::from(1000)],
                [U256::from(55), U256::MAX, U256::from(1000)],
            ],
        );
        let first = ctf_raw_single(0x22, 0x11, token1, U256::MAX);
        let second = ctf_raw_single(0x22, 0x11, token1, U256::ONE);
        transaction_total_overflow.inventory_logs = Some(vec![
            json!({"address":first.address,"topics":first.topics,"data":first.data}),
            json!({"address":second.address,"topics":second.topics,"data":second.data}),
        ]);
        transaction_total_overflow.extra_inventory_logs = Some(Vec::new());
        assert!(
            verify_complementary_root_fixture(
                &transaction_total_overflow,
                token_id,
                condition_id,
                1200,
                Duration::from_secs(10),
            )
            .await
            .is_err()
        );
    }

    #[tokio::test]
    async fn complementary_inventory_deadline_and_cancellation_cover_added_proof_phase() {
        let condition_id = B256::ZERO;
        let (mut fixture, token_id) = ctf_root_binary_identity_fixture(condition_id, 1);
        let identity = ctf_position_identity::derive_root_binary_identity_bounded(
            condition_id,
            token_id.value(),
            tokio::time::Instant::now() + Duration::from_secs(10),
        )
        .await
        .unwrap();
        install_condition_state_roots(
            &mut fixture,
            &identity,
            [
                [U256::ZERO; 4],
                [U256::from(2), U256::ZERO, U256::ZERO, U256::ZERO],
                [U256::from(2), U256::from(4), U256::from(1), U256::from(3)],
            ],
        );
        tokio::time::pause();
        fixture.initial_clock_advance_ms = Some(500);
        let gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        fixture.complementary_proof_gate = Some(gate.clone());
        let (opening, closing, quiet, _) = ctf_inventory_headers_with_102(&fixture);
        let intervals = intervals_from_headers(&opening, &closing, &quiet);
        let primary = ctf_inventory_provider(fixture.clone()).await;
        let secondary = ctf_inventory_provider(fixture.clone()).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let owner = format!("{:#x}", test_owner());
        let verification = verifier
            .verify_v1_trade_attribution_intervals_with_complementary_inventory_bounded(
                &owner,
                token_id,
                condition_id.0,
                &intervals,
                1200,
                Duration::from_secs(1),
            );
        tokio::pin!(verification);
        let clock_started = tokio::time::Instant::now();
        tokio::select! {
            result = &mut verification => panic!("complement proof gate returned early: {result:?}"),
            _ = gate.started.notified() => {}
            _ = test_wall_timeout(Duration::from_secs(30)) => panic!("complement proof gate was not reached before wall bound"),
        }
        assert_eq!(
            tokio::time::Instant::now().duration_since(clock_started),
            Duration::from_millis(500),
            "fixture must consume half the virtual budget before entering the late proof"
        );
        tokio::time::advance(Duration::from_millis(600)).await;
        let result = tokio::select! {
            result = &mut verification => result,
            _ = test_wall_timeout(Duration::from_secs(30)) => panic!("complement deadline did not settle after advancing past its deadline"),
        };
        assert_eq!(result, Err(BoundedV1TradeAttributionError::Timeout));
        gate.release.send(true).unwrap();
        tokio::time::resume();

        let gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        fixture.complementary_proof_gate = Some(gate.clone());
        let primary = ctf_inventory_provider(fixture.clone()).await;
        let secondary = ctf_inventory_provider(fixture).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        {
            let verification = verifier
                .verify_v1_trade_attribution_intervals_with_complementary_inventory_bounded(
                    &owner,
                    token_id,
                    condition_id.0,
                    &intervals,
                    1200,
                    Duration::from_secs(10),
                );
            tokio::pin!(verification);
            tokio::select! {
                result = &mut verification => panic!("complement proof gate returned early: {result:?}"),
                _ = gate.started.notified() => {}
                _ = test_wall_timeout(Duration::from_secs(30)) => panic!("complement cancellation gate was not reached before wall bound"),
            }
        }
        let _ = gate.release.send(true);
    }

