    #[tokio::test]
    async fn condition_state_storage_proof_shape_and_root_tampering_refuse() {
        let condition_id = B256::ZERO;
        let (base, token_id) = ctf_root_binary_identity_fixture(condition_id, 1);
        let identity = ctf_position_identity::derive_root_binary_identity_bounded(
            condition_id,
            token_id.value(),
            tokio::time::Instant::now() + Duration::from_secs(10),
        )
        .await
        .unwrap();
        for mutation in 0..8 {
            let mut fixture = base.clone();
            install_condition_state_roots(&mut fixture, &identity, [[U256::ZERO; 4]; 3]);
            let proof = fixture.post_condition_proof.as_mut().unwrap();
            match mutation {
                0 => proof["storageProof"].as_array_mut().unwrap().pop(),
                1 => {
                    let first = proof["storageProof"][0].clone();
                    proof["storageProof"].as_array_mut().unwrap().push(first);
                    None
                }
                2 => {
                    let extra = proof["storageProof"][0].clone();
                    proof["storageProof"].as_array_mut().unwrap().push(extra);
                    None
                }
                3 => {
                    proof["storageProof"][0]["key"] = json!(format!("0x{}", "ff".repeat(32)));
                    None
                }
                4 => {
                    proof["storageProof"][0]["value"] = json!("0x1");
                    None
                }
                5 => {
                    proof["codeHash"] = json!(format!("0x{}", "00".repeat(32)));
                    None
                }
                6 => {
                    proof["storageProof"][0]["proof"] = json!(["0x00"]);
                    None
                }
                _ => {
                    proof["storageHash"] = json!(format!("0x{}", "00".repeat(32)));
                    None
                }
            };
            let (opening, closing, _, _) = ctf_inventory_headers_with_102(&fixture);
            let interval = V1TradeAttributionIntervalAnchor {
                from_block: 100,
                through_block: 100,
                expected_parent_hash: opening["hash"].as_str().unwrap().to_owned(),
                expected_end_hash: closing["hash"].as_str().unwrap().to_owned(),
            };
            let primary = ctf_inventory_provider(fixture.clone()).await;
            let secondary = ctf_inventory_provider(fixture).await;
            let result = ChainLogVerifier::new(&primary, &secondary)
                .unwrap()
                .verify_v1_trade_attribution_intervals_with_ctf_condition_state_bounded(
                    &format!("{:#x}", test_owner()),
                    token_id,
                    condition_id.0,
                    std::slice::from_ref(&interval),
                    1000,
                    Duration::from_secs(10),
                )
                .await;
            assert!(result.is_err(), "proof mutation {mutation} must refuse");
        }
    }

    #[tokio::test]
    async fn condition_state_added_phase_uses_shared_budget_deadline_and_cancellation() {
        let condition_id = B256::ZERO;
        let (mut identity_fixture, token_id) = ctf_root_binary_identity_fixture(condition_id, 1);
        let identity = ctf_position_identity::derive_root_binary_identity_bounded(
            condition_id,
            token_id.value(),
            tokio::time::Instant::now() + Duration::from_secs(10),
        )
        .await
        .unwrap();
        let states = [
            [U256::ZERO; 4],
            [U256::from(2), U256::ZERO, U256::ZERO, U256::ZERO],
            [U256::from(2), U256::from(4), U256::ONE, U256::from(3)],
        ];
        install_condition_state_roots(&mut identity_fixture, &identity, states);
        let (opening, closing, quiet, _) = ctf_inventory_headers_with_102(&identity_fixture);
        let intervals = intervals_from_headers(&opening, &closing, &quiet);
        let primary = ctf_inventory_provider(identity_fixture.clone()).await;
        let secondary = ctf_inventory_provider(identity_fixture.clone()).await;
        ChainLogVerifier::new(&primary, &secondary)
            .unwrap()
            .verify_v1_trade_attribution_intervals_with_ctf_identity_bounded(
                &format!("{:#x}", test_owner()),
                token_id,
                condition_id.0,
                &intervals,
                1000,
                Duration::from_secs(10),
            )
            .await
            .unwrap();
        let identity_sends = identity_fixture.requests.load(Ordering::Relaxed);
        let (mut budget_fixture, budget_token) = ctf_root_binary_identity_fixture(condition_id, 1);
        install_condition_state_roots(&mut budget_fixture, &identity, states);
        let (opening, closing, quiet, _) = ctf_inventory_headers_with_102(&budget_fixture);
        let intervals = intervals_from_headers(&opening, &closing, &quiet);
        let primary = ctf_inventory_provider(budget_fixture.clone()).await;
        let secondary = ctf_inventory_provider(budget_fixture.clone()).await;
        let result = ChainLogVerifier::new(&primary, &secondary)
            .unwrap()
            .verify_v1_trade_attribution_intervals_with_ctf_condition_state_bounded(
                &format!("{:#x}", test_owner()),
                budget_token,
                condition_id.0,
                &intervals,
                identity_sends + 7,
                Duration::from_secs(10),
            )
            .await;
        assert_eq!(
            result,
            Err(BoundedV1TradeAttributionError::RequestBudgetExceeded)
        );
        let condition_phase_sends = budget_fixture.requests.load(Ordering::Relaxed);
        assert!(condition_phase_sends > identity_sends);
        assert!(condition_phase_sends <= identity_sends + 7);
        assert_eq!(
            budget_fixture.rpc_capture.lock().unwrap().last().unwrap()["params"][1]
                .as_array()
                .unwrap()
                .len(),
            4
        );

        let (mut deadline_fixture, deadline_token) =
            ctf_root_binary_identity_fixture(condition_id, 1);
        install_condition_state_roots(&mut deadline_fixture, &identity, states);
        tokio::time::pause();
        deadline_fixture.initial_clock_advance_ms = Some(500);
        let gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        deadline_fixture.condition_state_proof_gate = Some(gate.clone());
        let (opening, closing, quiet, _) = ctf_inventory_headers_with_102(&deadline_fixture);
        let intervals = intervals_from_headers(&opening, &closing, &quiet);
        let primary = ctf_inventory_provider(deadline_fixture.clone()).await;
        let secondary = ctf_inventory_provider(deadline_fixture.clone()).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let task = tokio::spawn(async move {
            verifier
                .verify_v1_trade_attribution_intervals_with_ctf_condition_state_bounded(
                    &format!("{:#x}", test_owner()),
                    deadline_token,
                    condition_id.0,
                    &intervals,
                    1000,
                    Duration::from_secs(1),
                )
                .await
        });
        let mut task = task;
        let clock_started = tokio::time::Instant::now();
        wait_for_identity_proof_gate(&gate, &mut task, Duration::from_secs(30)).await;
        assert_eq!(
            tokio::time::Instant::now().duration_since(clock_started),
            Duration::from_millis(500),
            "fixture must consume half the virtual budget before entering the late proof"
        );
        tokio::time::advance(Duration::from_millis(600)).await;
        let result = tokio::select! {
            result = &mut task => result.unwrap(),
            _ = test_wall_timeout(Duration::from_secs(30)) => panic!("deadline result did not settle after advancing past its deadline"),
        };
        assert_eq!(result, Err(BoundedV1TradeAttributionError::Timeout));
        gate.release.send(true).unwrap();
        tokio::time::resume();

        let (mut cancel_fixture, cancel_token) = ctf_root_binary_identity_fixture(condition_id, 1);
        install_condition_state_roots(&mut cancel_fixture, &identity, states);
        let gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        cancel_fixture.condition_state_proof_gate = Some(gate.clone());
        let (opening, closing, quiet, _) = ctf_inventory_headers_with_102(&cancel_fixture);
        let intervals = intervals_from_headers(&opening, &closing, &quiet);
        let primary = ctf_inventory_provider(cancel_fixture.clone()).await;
        let secondary = ctf_inventory_provider(cancel_fixture.clone()).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let task = tokio::spawn(async move {
            verifier
                .verify_v1_trade_attribution_intervals_with_ctf_condition_state_bounded(
                    &format!("{:#x}", test_owner()),
                    cancel_token,
                    condition_id.0,
                    &intervals,
                    1000,
                    Duration::from_secs(10),
                )
                .await
        });
        let mut task = task;
        wait_for_identity_proof_gate(&gate, &mut task, Duration::from_secs(30)).await;
        let sent = cancel_fixture.requests.load(Ordering::Relaxed);
        task.abort();
        assert!(task.await.unwrap_err().is_cancelled());
        gate.release.send(true).unwrap();
        tokio::time::sleep(Duration::from_millis(20)).await;
        assert_eq!(cancel_fixture.requests.load(Ordering::Relaxed), sent);
    }

    #[tokio::test]
    async fn root_consistent_registry_mismatches_and_malformed_entries_refuse_identity() {
        let condition_id = B256::ZERO;
        let (base, token_id) = ctf_root_binary_identity_fixture(condition_id, 1);
        let derived_values = [
            U256::from_be_slice(
                &hex::decode("39d1e2a4ed795f9ec6a9b77a43bd4ac1256a2aee3dbd039eafa840db53ec0b47")
                    .unwrap(),
            ),
            U256::ZERO,
            token_id.value(),
            U256::ZERO,
        ];
        let mut wrong_mirror = derived_values;
        wrong_mirror[0] = U256::from(77_u64);
        let mut wrong_condition = derived_values;
        wrong_condition[1] = U256::ONE;
        wrong_condition[3] = U256::ONE;
        let mut unregistered = derived_values;
        unregistered[0] = U256::ZERO;
        let mut arbitrary_admin_pair = derived_values;
        arbitrary_admin_pair[0] = U256::from(0x1234_u64);

        for values in [
            wrong_mirror,
            wrong_condition,
            unregistered,
            arbitrary_admin_pair,
        ] {
            let (fixture, selected) =
                ctf_root_binary_identity_fixture_with_values(condition_id, 1, Some(values), None);
            assert_eq!(selected, token_id);
            assert_eq!(
                verify_ctf_root_binary_identity_fixture(
                    &fixture,
                    selected,
                    condition_id,
                    1000,
                    Duration::from_secs(10),
                )
                .await,
                Err(BoundedV1TradeAttributionError::Verification(
                    ChainLogAuditError::Unverified
                ))
            );
        }

        let (wrong_codehash_fixture, _) = ctf_root_binary_identity_fixture_with_values(
            condition_id,
            1,
            None,
            Some(B256::repeat_byte(0x99)),
        );
        assert_eq!(
            verify_ctf_root_binary_identity_fixture(
                &wrong_codehash_fixture,
                token_id,
                condition_id,
                1000,
                Duration::from_secs(10),
            )
            .await,
            Err(BoundedV1TradeAttributionError::Verification(
                ChainLogAuditError::Unverified
            ))
        );
        let (divergent_fixture, _) =
            ctf_root_binary_identity_fixture_with_values(condition_id, 1, Some(wrong_mirror), None);
        let (opening, closing, _, _) = ctf_inventory_headers_with_102(&base);
        let primary = ctf_inventory_provider(base.clone()).await;
        let secondary = ctf_inventory_provider(divergent_fixture).await;
        let divergent_intervals = [V1TradeAttributionIntervalAnchor {
            from_block: 100,
            through_block: 100,
            expected_parent_hash: opening["hash"].as_str().unwrap().to_owned(),
            expected_end_hash: closing["hash"].as_str().unwrap().to_owned(),
        }];
        assert_eq!(
            ChainLogVerifier::new(&primary, &secondary)
                .unwrap()
                .verify_v1_trade_attribution_intervals_with_ctf_identity_bounded(
                    &format!("{:#x}", test_owner()),
                    token_id,
                    condition_id.0,
                    &divergent_intervals,
                    1000,
                    Duration::from_secs(10),
                )
                .await,
            Err(BoundedV1TradeAttributionError::Verification(
                ChainLogAuditError::Divergent
            ))
        );

        for malformed in [
            "missing",
            "extra",
            "duplicate",
            "foreign_key",
            "changed_value",
            "wrong_storage_root",
            "wrong_account",
        ] {
            let mut fixture = base.clone();
            for proof in [
                &mut fixture.opening_exchange_proof,
                &mut fixture.post_exchange_proof,
                &mut fixture.extra_post_exchange_proof,
            ] {
                let proof = proof.as_mut().unwrap();
                match malformed {
                    "missing" => {
                        proof["storageProof"].as_array_mut().unwrap().pop();
                    }
                    "extra" => {
                        let first = proof["storageProof"][0].clone();
                        proof["storageProof"].as_array_mut().unwrap().push(first);
                    }
                    "duplicate" => {
                        let first_key = proof["storageProof"][0]["key"].clone();
                        proof["storageProof"][1]["key"] = first_key;
                    }
                    "foreign_key" => {
                        proof["storageProof"][0]["key"] = json!(format!("0x{}", "77".repeat(32)))
                    }
                    "changed_value" => proof["storageProof"][0]["value"] = json!("0x1"),
                    "wrong_storage_root" => {
                        proof["storageHash"] = json!(format!("0x{}", "88".repeat(32)))
                    }
                    "wrong_account" => proof["address"] = json!(format!("0x{}", "99".repeat(20))),
                    _ => unreachable!(),
                }
            }
            assert!(
                verify_ctf_root_binary_identity_fixture(
                    &fixture,
                    token_id,
                    condition_id,
                    1000,
                    Duration::from_secs(10),
                )
                .await
                .is_err(),
                "malformed={malformed}"
            );
        }

        let (mismatch_fixture, _) = ctf_root_binary_identity_fixture(condition_id, 1);
        let primary = ctf_inventory_provider(mismatch_fixture.clone()).await;
        let secondary = ctf_inventory_provider(mismatch_fixture.clone()).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let wrong_token = test_token_id();
        assert_eq!(
            verifier
                .verify_v1_trade_attribution_intervals_with_ctf_identity_bounded(
                    &format!("{:#x}", test_owner()),
                    wrong_token,
                    condition_id.0,
                    &[V1TradeAttributionIntervalAnchor {
                        from_block: 100,
                        through_block: 100,
                        expected_parent_hash: ctf_inventory_headers_with_102(&base).0["hash"]
                            .as_str()
                            .unwrap()
                            .to_owned(),
                        expected_end_hash: ctf_inventory_headers_with_102(&base).1["hash"]
                            .as_str()
                            .unwrap()
                            .to_owned(),
                    },],
                    1000,
                    Duration::from_secs(10),
                )
                .await,
            Err(BoundedV1TradeAttributionError::Verification(
                ChainLogAuditError::InvalidInput
            ))
        );
        assert_eq!(
            mismatch_fixture
                .requests
                .load(std::sync::atomic::Ordering::Relaxed),
            0,
            "selected token mismatch must be rejected before RPC sends"
        );
    }

