    #[tokio::test]
    async fn root_verified_v1_binary_fill_orders_proves_both_owner_maker_approval_paths() {
        let owner = test_owner();
        let owner_text = format!("{owner:#x}");
        let condition_id = B256::ZERO;
        let (_, token_id) = ctf_root_binary_identity_fixture(condition_id, 1);
        let identity = ctf_position_identity::derive_root_binary_identity_bounded(
            condition_id,
            token_id.value(),
            tokio::time::Instant::now() + Duration::from_secs(10),
        )
        .await
        .unwrap();
        let buy_input = test_v1_fill_order_input(
            &owner_text,
            token_id.value(),
            U256::from(9_000_000_u64),
            U256::from(18_000_000_u64),
            U256::from(100_u64),
            V1DirectFillSide::Buy,
            U256::from(9_000_000_u64),
        );
        let sell_input = test_v1_fill_order_input(
            &owner_text,
            token_id.value(),
            U256::from(18_000_000_u64),
            U256::from(9_000_000_u64),
            U256::from(100_u64),
            V1DirectFillSide::Sell,
            U256::from(9_000_000_u64),
        );
        let input = test_v1_fill_orders_input_many(
            &[&buy_input, &sell_input],
            &[U256::from(9_000_000_u64), U256::from(9_000_000_u64)],
        );
        assert_eq!(
            v1_binary_trades::decode_v1_direct_orders(&input)
                .unwrap()
                .len(),
            2
        );
        let (signed_transaction, operator) =
            signed_polygon_transaction_with_key(EXCHANGES[0], &input, 0x57);
        assert_ne!(operator, owner_text);
        let orders = [
            decode_v1_direct_order_call(&buy_input).unwrap(),
            decode_v1_direct_order_call(&sell_input).unwrap(),
        ];
        let mut logs = Vec::new();
        let mut total_position = U256::ZERO;
        let mut closing_cash = U256::from(20_000_000_u64);
        for order in &orders {
            let taking =
                checked_mul_div(order.fill_amount, order.taker_amount, order.maker_amount).unwrap();
            let fee = calculate_v1_direct_fill_fee(order, taking).unwrap();
            let net = taking - fee;
            let (maker_asset, taker_asset) = order_asset_ids(order);
            logs.push(test_asset_transfer(
                taker_asset,
                &operator,
                &order.maker,
                net,
                logs.len() as u64,
            ));
            if taker_asset.is_zero() {
                logs.push(test_erc20_approval(
                    &operator,
                    EXCHANGES[0],
                    net,
                    logs.len() as u64,
                ));
            }
            logs.push(test_asset_transfer(
                maker_asset,
                &order.maker,
                &operator,
                order.fill_amount,
                logs.len() as u64,
            ));
            if maker_asset.is_zero() {
                logs.push(test_erc20_approval(
                    &order.maker,
                    EXCHANGES[0],
                    order.fill_amount,
                    logs.len() as u64,
                ));
            }
            logs.push(test_order_filled_log(
                &v1_order_hash(order).unwrap(),
                &order.maker,
                &operator,
                maker_asset,
                taker_asset,
                order.fill_amount,
                taking,
                fee,
                logs.len() as u64,
            ));
            match order.side {
                V1DirectFillSide::Buy => {
                    total_position = total_position.checked_add(net).unwrap();
                    closing_cash = closing_cash.checked_sub(order.fill_amount).unwrap();
                }
                V1DirectFillSide::Sell => {
                    total_position = total_position.checked_sub(order.fill_amount).unwrap();
                    closing_cash = closing_cash.checked_add(net).unwrap();
                }
            }
        }
        for (index, log) in logs.iter_mut().enumerate() {
            log.block_log_index = index as u64;
        }
        let selected_index = usize::from(identity.selected_index_set - 1);
        let mut closing_positions = [U256::ZERO; 2];
        closing_positions[selected_index] = total_position;
        let fixture = ctf_inventory_fixture_with_binary_match_orders(
            logs.clone(),
            signed_transaction.clone(),
            owner,
            token_id,
            &identity,
            [U256::ZERO; 2],
            U256::from(20_000_000_u64),
            closing_positions,
            closing_cash,
        );
        let capture = fixture.rpc_capture.clone();
        let (opening, closing, _) = ctf_inventory_headers(&fixture);
        let interval = [V1TradeAttributionIntervalAnchor {
            from_block: 100,
            through_block: 100,
            expected_parent_hash: opening["hash"].as_str().unwrap().to_owned(),
            expected_end_hash: closing["hash"].as_str().unwrap().to_owned(),
        }];
        let primary = ctf_inventory_provider(fixture.clone()).await;
        let secondary = ctf_inventory_provider(fixture).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let reports = verifier
            .verify_v1_trade_attribution_intervals_with_binary_trades_bounded(
                &owner_text,
                token_id,
                condition_id.0,
                &interval,
                500,
                Duration::from_secs(10),
            )
            .await
            .unwrap_or_else(|error| panic!("{error:?}"));
        let evidence = reports[0].v1_binary_trades().unwrap();
        assert!(
            evidence.complete_for_binary_trade_scope(),
            "transactions={:?}; lifecycle={}",
            evidence.transactions(),
            evidence.inventory_and_lifecycle_consistent()
        );
        assert_eq!(evidence.trades().len(), 2);
        assert_eq!(
            evidence.trades()[0].kind,
            V1TradeAttributionKind::DirectFill
        );
        assert_eq!(
            evidence.trades()[1].kind,
            V1TradeAttributionKind::DirectFill
        );
        assert_ne!(
            evidence.trades()[0].order_filled_log_index,
            evidence.trades()[1].order_filled_log_index
        );
        assert!(
            logs.iter()
                .any(|log| ctf_operations::usdc_transfer_from_approval_matches(
                    log,
                    &owner_text,
                    EXCHANGES[0],
                    U256::from(9_000_000_u64)
                ))
        );
        assert!(
            logs.iter()
                .any(|log| ctf_operations::usdc_transfer_from_approval_matches(
                    log,
                    &operator,
                    EXCHANGES[0],
                    U256::from(4_455_000_u64)
                ))
        );

        if let Ok(path) = std::env::var("PDH_CAPTURE_V1_BINARY_TRADES_DIRECT_FIXTURE") {
            let mut unique = BTreeMap::new();
            for response in capture.lock().unwrap().iter() {
                let key = serde_json::to_string(&json!([response["method"], response["params"]]))
                    .unwrap();
                unique.insert(key, response.clone());
            }
            let captured_fixture = json!({
                "provenance":"Captured from deterministic root-verified loopback V1 fillOrders with two nonzero-fee owner-maker fills (BUY and SELL); includes signed transaction, receipt/transaction tries, paired owner and Exchange inventory proofs, source-ordered ERC20 Transfer+Approval logs, and CTF movements. No external RPC/data/secrets.",
                "owner":owner_text,"token_id":format!("{:#x}",token_id.value()),"condition_id":format!("{condition_id:#x}"),
                "from_block":100,"through_block":100,"parent_hash":reports[0].paired_inventory().parent_hash(),"end_hash":reports[0].paired_inventory().end_hash(),
                "rpc_responses":unique.into_values().collect::<Vec<_>>()
            });
            let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../")
                .join(path);
            std::fs::write(path, serde_json::to_vec(&captured_fixture).unwrap()).unwrap();
        }
    }

    #[tokio::test]
    async fn root_verified_v1_binary_fill_orders_maps_owner_operator_legs_and_fee_once() {
        let condition_id = B256::ZERO;
        let (_, token_id) = ctf_root_binary_identity_fixture(condition_id, 1);
        let identity = ctf_position_identity::derive_root_binary_identity_bounded(
            condition_id,
            token_id.value(),
            tokio::time::Instant::now() + Duration::from_secs(10),
        )
        .await
        .unwrap();
        let maker = format!("0x{}", "22".repeat(20));
        let order_input = test_v1_fill_order_input(
            &maker,
            token_id.value(),
            U256::from(9_000_000_u64),
            U256::from(1_000_000_u64),
            U256::from(100_u64),
            V1DirectFillSide::Sell,
            U256::from(9_000_000_u64),
        );
        let input = test_v1_fill_orders_input_many(&[&order_input], &[U256::from(9_000_000_u64)]);
        let (signed_transaction, owner_text) =
            signed_polygon_transaction_with_key(EXCHANGES[0], &input, 0x58);
        let owner = Address::from_slice(&hex::decode(&owner_text[2..]).unwrap());
        let order = decode_v1_direct_order_call(&order_input).unwrap();
        let taking =
            checked_mul_div(order.fill_amount, order.taker_amount, order.maker_amount).unwrap();
        let fee = calculate_v1_direct_fill_fee(&order, taking).unwrap();
        let net = taking - fee;
        let (maker_asset, taker_asset) = order_asset_ids(&order);
        let mut logs = vec![
            test_erc20_transfer(&owner_text, &maker, net, 0),
            test_erc20_approval(&owner_text, EXCHANGES[0], net, 1),
            test_transfer_single(&maker, &owner_text, token_id.value(), order.fill_amount, 2),
            test_order_filled_log(
                &v1_order_hash(&order).unwrap(),
                &maker,
                &owner_text,
                maker_asset,
                taker_asset,
                order.fill_amount,
                taking,
                fee,
                3,
            ),
        ];
        for (index, log) in logs.iter_mut().enumerate() {
            log.block_log_index = index as u64;
        }
        let selected_index = usize::from(identity.selected_index_set - 1);
        let mut closing_positions = [U256::ZERO; 2];
        closing_positions[selected_index] = order.fill_amount;
        let opening_cash = U256::from(2_000_000_u64);
        let closing_cash = opening_cash - net;
        let fixture = ctf_inventory_fixture_with_binary_match_orders(
            logs.clone(),
            signed_transaction,
            owner,
            token_id,
            &identity,
            [U256::ZERO; 2],
            opening_cash,
            closing_positions,
            closing_cash,
        );
        let (opening, closing, _) = ctf_inventory_headers(&fixture);
        let interval = [V1TradeAttributionIntervalAnchor {
            from_block: 100,
            through_block: 100,
            expected_parent_hash: opening["hash"].as_str().unwrap().to_owned(),
            expected_end_hash: closing["hash"].as_str().unwrap().to_owned(),
        }];
        let primary = ctf_inventory_provider(fixture.clone()).await;
        let secondary = ctf_inventory_provider(fixture).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let reports = verifier
            .verify_v1_trade_attribution_intervals_with_binary_trades_bounded(
                &owner_text,
                token_id,
                condition_id.0,
                &interval,
                500,
                Duration::from_secs(10),
            )
            .await
            .unwrap();
        let trade = &reports[0].v1_binary_trades().unwrap().trades()[0];
        assert_eq!(trade.kind, V1TradeAttributionKind::DirectFill);
        assert_eq!(trade.gross_making_amount, net);
        assert_eq!(trade.gross_received_amount, order.fill_amount);
        assert_eq!(trade.received_fee_amount, U256::ZERO);
        assert_eq!(
            trade.owner_collateral_direction,
            V1DirectFillAssetDirection::Out
        );
        assert_eq!(trade.owner_collateral_amount, net);
        assert_eq!(trade.owner_token_direction, V1DirectFillAssetDirection::In);
        assert_eq!(trade.owner_token_amount, order.fill_amount);
        assert_eq!(trade.making_transfer_log_index, 0);
        assert_eq!(trade.receiving_transfer_log_index, 2);
        assert_eq!(trade.order_filled_log_index, 3);
    }

