    #[tokio::test]
    async fn fifth_native_binary_module_uses_actual_shared_budget_and_absolute_deadline() {
        use super::BoundedFifthNativeBinaryModuleOperationsError;
        use super::FifthNativeBinaryModuleOperationsStatus;
        use std::sync::atomic::Ordering;

        for (cross_block, successful_budget, exhausted_budget) in
            [(false, 74, 73), (true, 118, 117)]
        {
            let (fixture, owner, condition, parent, end, through) =
                fifth_native_module_operation_fixture("split", cross_block, false);
            let (primary, primary_task) = serve_direct_module_fixture(fixture.clone()).await;
            let (secondary, secondary_task) = serve_direct_module_fixture(fixture.clone()).await;
            let report = ChainLogVerifier::new(&primary, &secondary)
                .unwrap()
                .verify_fifth_native_binary_module_operations_interval_bounded(
                    &owner,
                    &format!("{condition:#x}"),
                    100,
                    through,
                    &parent,
                    &end,
                    successful_budget,
                    Duration::from_secs(10),
                )
                .await
                .unwrap();
            assert_eq!(
                report.status(),
                &FifthNativeBinaryModuleOperationsStatus::Matched
            );
            assert_eq!(fixture.requests.load(Ordering::Relaxed), successful_budget);
            primary_task.abort();
            secondary_task.abort();

            let (fixture, owner, condition, parent, end, through) =
                fifth_native_module_operation_fixture("split", cross_block, false);
            let (primary, primary_task) = serve_direct_module_fixture(fixture.clone()).await;
            let (secondary, secondary_task) = serve_direct_module_fixture(fixture.clone()).await;
            let result = ChainLogVerifier::new(&primary, &secondary)
                .unwrap()
                .verify_fifth_native_binary_module_operations_interval_bounded(
                    &owner,
                    &format!("{condition:#x}"),
                    100,
                    through,
                    &parent,
                    &end,
                    exhausted_budget,
                    Duration::from_secs(10),
                )
                .await;
            assert_eq!(
                result,
                Err(BoundedFifthNativeBinaryModuleOperationsError::RequestBudgetExceeded)
            );
            let sends = fixture.requests.load(Ordering::Relaxed);
            assert!(sends + 1 >= exhausted_budget && sends <= exhausted_budget);
            primary_task.abort();
            secondary_task.abort();
        }

        tokio::time::pause();
        let (mut fixture, owner, condition, parent, end, through) =
            fifth_native_module_operation_fixture("split", true, false);
        fixture.initial_clock_advance_ms = Some(500);
        fixture.initial_clock_advance_once =
            std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let deadline_gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        fixture.direct_module_boundary_proof_gate = Some(deadline_gate.clone());
        let (primary, primary_task) = serve_direct_module_fixture(fixture.clone()).await;
        let (secondary, secondary_task) = serve_direct_module_fixture(fixture.clone()).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let task_owner = owner.clone();
        let task_condition = condition;
        let task_parent = parent.clone();
        let task_end = end.clone();
        let clock_started = tokio::time::Instant::now();
        let mut deadline_task = tokio::spawn(async move {
            verifier
                .verify_fifth_native_binary_module_operations_interval_bounded(
                    &task_owner,
                    &format!("{task_condition:#x}"),
                    100,
                    through,
                    &task_parent,
                    &task_end,
                    118,
                    Duration::from_secs(1),
                )
                .await
        });
        wait_for_identity_proof_gate(&deadline_gate, &mut deadline_task, Duration::from_secs(30))
            .await;
        assert_eq!(
            tokio::time::Instant::now().duration_since(clock_started),
            Duration::from_millis(500)
        );
        tokio::time::advance(Duration::from_millis(600)).await;
        let deadline_result = tokio::select! {
            result = &mut deadline_task => result.unwrap(),
            _ = test_wall_timeout(Duration::from_secs(30)) => panic!("native module deadline did not settle"),
        };
        deadline_gate.release.send_replace(true);
        assert_eq!(
            deadline_result,
            Err(BoundedFifthNativeBinaryModuleOperationsError::Timeout)
        );
        tokio::time::resume();
        primary_task.abort();
        secondary_task.abort();

        let (mut fixture, owner, condition, parent, end, through) =
            fifth_native_module_operation_fixture("split", true, false);
        let cancel_gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        fixture.direct_module_boundary_proof_gate = Some(cancel_gate.clone());
        let (primary, primary_task) = serve_direct_module_fixture(fixture.clone()).await;
        let (secondary, secondary_task) = serve_direct_module_fixture(fixture.clone()).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let task_owner = owner.clone();
        let task_condition = condition;
        let mut cancelled = tokio::spawn(async move {
            verifier
                .verify_fifth_native_binary_module_operations_interval_bounded(
                    &task_owner,
                    &format!("{task_condition:#x}"),
                    100,
                    through,
                    &parent,
                    &end,
                    118,
                    Duration::from_secs(10),
                )
                .await
        });
        wait_for_identity_proof_gate(&cancel_gate, &mut cancelled, Duration::from_secs(30)).await;
        let sent_before_abort = fixture.requests.load(Ordering::Relaxed);
        cancelled.abort();
        assert!(cancelled.await.unwrap_err().is_cancelled());
        cancel_gate.release.send_replace(true);
        tokio::time::sleep(Duration::from_millis(50)).await;
        assert_eq!(fixture.requests.load(Ordering::Relaxed), sent_before_abort);
        primary_task.abort();
        secondary_task.abort();
    }

    #[tokio::test]
    async fn fifth_native_binary_module_refuses_wrong_owner_and_reordered_source_logs() {
        use super::FifthNativeBinaryModuleOperationsStatus;

        let (mut fixture, owner, condition, _, _, through) =
            fifth_native_module_operation_fixture("split", false, false);
        let operation = fixture
            .rooted_gas_block
            .as_mut()
            .unwrap()
            .transactions
            .get_mut(1)
            .unwrap();
        let calldata = hex::decode(
            operation["input"]
                .as_str()
                .unwrap()
                .trim_start_matches("0x"),
        )
        .unwrap();
        let (wrong_sender, recovered) = signed_polygon_call_with_seed(
            "0x3333333333333333333333333333333333333333",
            &calldata,
            1,
            [0x43; 32],
        );
        assert_ne!(recovered, owner);
        *operation = wrong_sender;
        let report = verify_fifth_native_module_fixture(&fixture, &owner, condition, through, 200)
            .await
            .unwrap();
        assert!(matches!(
            report.status(),
            FifthNativeBinaryModuleOperationsStatus::Unavailable { .. }
        ));
        assert!(report.operations().is_empty());

        let (mut fixture, owner, condition, _, _, through) =
            fifth_native_module_operation_fixture("split", false, false);
        fixture.rooted_gas_block.as_mut().unwrap().receipt_logs[1].reverse();
        let report = verify_fifth_native_module_fixture(&fixture, &owner, condition, through, 200)
            .await
            .unwrap();
        assert!(matches!(
            report.status(),
            FifthNativeBinaryModuleOperationsStatus::Unavailable { .. }
        ));
        assert!(report.operations().is_empty());
    }

    #[tokio::test]
    async fn fifth_native_binary_module_refuses_middle_mismatch_opening_stock_and_result_change() {
        use super::FifthNativeBinaryModuleOperationsStatus;

        let (mut fixture, owner, condition, _, _, through) =
            fifth_native_module_operation_fixture("split", true, false);
        let (bad_root, bad_proofs) =
            fifth_legacy_binary_balances::test_rooted_native_module_operation_point_packet(
                &owner,
                condition,
                [U256::ZERO; 2],
                U256::ZERO,
                [U256::ZERO; 2],
                U256::from(9),
                U256::ONE,
                [U256::ZERO; 3],
            );
        fixture.post_state = Some((bad_root, Value::Null));
        fixture
            .fifth_code_proofs_by_block
            .as_mut()
            .unwrap()
            .insert(100, bad_proofs);
        let report = verify_fifth_native_module_fixture(&fixture, &owner, condition, through, 200)
            .await
            .unwrap();
        assert!(matches!(
            report.status(),
            FifthNativeBinaryModuleOperationsStatus::Mismatch {
                block_number: 100,
                holder:
                    super::fifth_direct_module_operations::FifthDirectModuleOperationsHolder::Module,
                asset:
                    super::fifth_direct_module_operations::FifthDirectModuleOperationsAsset::Pusd,
                ..
            }
        ));
        assert!(report.operations().is_empty());

        let (mut fixture, owner, condition, _, _, through) =
            fifth_native_module_operation_fixture("split", false, false);
        let (stock_root, stock_proofs) =
            fifth_legacy_binary_balances::test_rooted_native_module_operation_point_packet(
                &owner,
                condition,
                [U256::ZERO; 2],
                U256::from(10),
                [U256::ONE, U256::ZERO],
                U256::ZERO,
                U256::ONE,
                [U256::ZERO; 3],
            );
        fixture.state_root = stock_root;
        fixture
            .fifth_code_proofs_by_block
            .as_mut()
            .unwrap()
            .insert(99, stock_proofs);
        let report = verify_fifth_native_module_fixture(&fixture, &owner, condition, through, 200)
            .await
            .unwrap();
        assert!(matches!(
            report.status(),
            FifthNativeBinaryModuleOperationsStatus::Unavailable {
                reason: super::fifth_direct_module_operations::FifthLegacyBinaryModuleOperationsUnavailableReason::ModuleNotEmpty,
                ..
            }
        ));
        assert!(report.operations().is_empty());

        let (mut fixture, owner, condition, _, _, through) =
            fifth_native_module_operation_fixture("split", false, false);
        let (changed_root, changed_proofs) =
            fifth_legacy_binary_balances::test_rooted_native_module_operation_point_packet(
                &owner,
                condition,
                [U256::from(10); 2],
                U256::ZERO,
                [U256::ZERO; 2],
                U256::ZERO,
                U256::ONE,
                [U256::from(2), U256::from(1_000_000), U256::ZERO],
            );
        fixture.post_state = Some((changed_root, Value::Null));
        fixture
            .fifth_code_proofs_by_block
            .as_mut()
            .unwrap()
            .insert(100, changed_proofs);
        let report = verify_fifth_native_module_fixture(&fixture, &owner, condition, through, 200)
            .await
            .unwrap();
        assert!(matches!(
            report.status(),
            FifthNativeBinaryModuleOperationsStatus::Unavailable { .. }
        ));
        assert!(report.operations().is_empty());

        let (mut fixture, owner, condition, _, _, through) =
            fifth_native_module_operation_fixture("split", false, false);
        let (no_role_root, no_role_proofs) =
            fifth_legacy_binary_balances::test_rooted_native_module_operation_point_packet(
                &owner,
                condition,
                [U256::ZERO; 2],
                U256::from(10),
                [U256::ZERO; 2],
                U256::ZERO,
                U256::ZERO,
                [U256::ZERO; 3],
            );
        fixture.state_root = no_role_root;
        fixture
            .fifth_code_proofs_by_block
            .as_mut()
            .unwrap()
            .insert(99, no_role_proofs);
        let report = verify_fifth_native_module_fixture(&fixture, &owner, condition, through, 200)
            .await
            .unwrap();
        assert!(matches!(
            report.status(),
            FifthNativeBinaryModuleOperationsStatus::Unavailable {
                reason: super::fifth_direct_module_operations::FifthLegacyBinaryModuleOperationsUnavailableReason::MinterRoleUnavailable,
                ..
            }
        ));
        assert!(report.operations().is_empty());

        let (mut fixture, owner, condition, _, _, through) =
            fifth_native_module_operation_fixture("split", false, false);
        let (residual_root, residual_proofs) =
            fifth_legacy_binary_balances::test_rooted_native_module_operation_point_packet(
                &owner,
                condition,
                [U256::from(10); 2],
                U256::ZERO,
                [U256::ZERO; 2],
                U256::ONE,
                U256::ONE,
                [U256::ZERO; 3],
            );
        fixture.post_state = Some((residual_root, Value::Null));
        fixture
            .fifth_code_proofs_by_block
            .as_mut()
            .unwrap()
            .insert(100, residual_proofs);
        let report = verify_fifth_native_module_fixture(&fixture, &owner, condition, through, 200)
            .await
            .unwrap();
        assert!(matches!(
            report.status(),
            FifthNativeBinaryModuleOperationsStatus::Mismatch {
                block_number: 100,
                holder:
                    super::fifth_direct_module_operations::FifthDirectModuleOperationsHolder::Module,
                asset:
                    super::fifth_direct_module_operations::FifthDirectModuleOperationsAsset::Pusd,
                ..
            }
        ));
        assert!(report.operations().is_empty());
    }

    #[tokio::test]
    async fn direct_binary_module_split_replays_rooted_owner_and_module_balances() {
        use super::fifth_code_context::POSITION_MANAGER_PROXY;
        use super::fifth_direct_module_operations::{
            FifthDirectModuleOperationKind, FifthLegacyBinaryModuleOperationsStatus,
        };

        const OWNER: &str = "0x17c5185167401ed00cf5f5b2fc97d9bbfdb7d025";
        const MODULE: &str = "0x3333333333333333333333333333333333333333";
        const LEGACY: &str = "0x1212121212121212121212121212121212121212121212121212121212121212";
        let legacy = parse_fixed_b256(LEGACY).unwrap();
        let mut condition_bytes = [0_u8; 32];
        condition_bytes[0] = 1;
        condition_bytes[1..17].copy_from_slice(&legacy.as_slice()[16..]);
        let condition = B256::from(condition_bytes);
        let mut id_a = condition.0;
        id_a[31] = 0;
        let mut id_b = condition.0;
        id_b[31] = 1;
        let ids = [B256::from(id_a), B256::from(id_b)];
        let (open_root, open_proofs) =
            fifth_legacy_binary_balances::test_rooted_module_point_proof_packet(
                OWNER,
                [U256::ZERO; 2],
                U256::from(10),
                [U256::ZERO; 2],
                U256::ZERO,
                U256::ONE,
            );
        let (end_root, end_proofs) =
            fifth_legacy_binary_balances::test_rooted_module_point_proof_packet(
                OWNER,
                [U256::from(10); 2],
                U256::ZERO,
                [U256::ZERO; 2],
                U256::ZERO,
                U256::ONE,
            );
        let mut fixture = ctf_inventory_fixture(U256::ZERO, 0);
        fixture.state_root = open_root;
        fixture.post_state = Some((end_root.clone(), Value::Null));
        fixture.finalized_block = 101;
        fixture.filter_fifth_code_proofs_by_requested_keys = true;
        fixture.fifth_code_proofs_by_block =
            Some(BTreeMap::from([(99, open_proofs), (100, end_proofs)]));

        let amount = U256::from(10);
        let split_call = vector_call("split-owner10");
        let fund_call = vector_call("pusd-fund-split10");
        let (fund_tx, from) = signed_polygon_owner_call(PUSD_PROXY_TEST, &fund_call, 0);
        assert_eq!(from, OWNER);
        let (split_tx, split_from) = signed_polygon_owner_call(MODULE, &split_call, 1);
        assert_eq!(split_from, OWNER);
        let logs = vec![
            vec![direct_event_log(
                PUSD_PROXY_TEST,
                ERC20_TRANSFER,
                vec![address_topic(OWNER), address_topic(MODULE)],
                movement_word(amount),
            )],
            vec![
                direct_event_log(
                    POSITION_MANAGER_PROXY,
                    ERC1155_TRANSFER_SINGLE,
                    vec![
                        address_topic(MODULE),
                        address_topic("0x0000000000000000000000000000000000000000"),
                        address_topic(OWNER),
                    ],
                    [
                        movement_word(U256::from_be_bytes(ids[0].0)),
                        movement_word(amount),
                    ]
                    .concat(),
                ),
                direct_event_log(
                    POSITION_MANAGER_PROXY,
                    ERC1155_TRANSFER_SINGLE,
                    vec![
                        address_topic(MODULE),
                        address_topic("0x0000000000000000000000000000000000000000"),
                        address_topic(OWNER),
                    ],
                    [
                        movement_word(U256::from_be_bytes(ids[1].0)),
                        movement_word(amount),
                    ]
                    .concat(),
                ),
                direct_event_log(
                    PUSD_PROXY_TEST,
                    ERC20_TRANSFER,
                    vec![
                        address_topic(MODULE),
                        address_topic("0x0000000000000000000000000000000000000000"),
                    ],
                    movement_word(amount),
                ),
                direct_event_log(
                    MODULE,
                    &movement_topic("PositionsSplit(address,bytes31,address,address,uint256)"),
                    vec![
                        address_topic(OWNER),
                        format!("{condition:#x}"),
                        address_topic(OWNER),
                    ],
                    [address_word_bytes(OWNER), movement_word(amount)].concat(),
                ),
            ],
        ];
        let rooted = RootedGasBlockFixture {
            transactions: vec![fund_tx, split_tx],
            receipt_logs: logs.into_iter().map(|rows| rows.into_iter().map(|log| json!({"address":log.address,"topics":log.topics,"data":log.data})).collect()).collect(),
            receipt_statuses: vec![1, 1], cumulative_gas_used: vec![21_000, 42_000],
            receipt_types: vec![0, 0], gas_limit: 1_000_000, base_fee_per_gas: U256::ZERO,
            header_gas_used_override: None, tamper_header_gas_used: false, tamper_cumulative_index: None,
        };
        fixture.rooted_gas_block = Some(rooted.clone());
        let (opening_header, closing_header, _) = ctf_inventory_headers(&fixture);
        let parent = opening_header["hash"].as_str().unwrap().to_owned();
        let end = closing_header["hash"].as_str().unwrap().to_owned();
        let primary = Arc::new(fixture.clone());
        let secondary = Arc::new(fixture);
        let (primary_endpoint, primary_task) =
            serve_direct_module_fixture(primary.as_ref().clone()).await;
        let (secondary_endpoint, secondary_task) =
            serve_direct_module_fixture(secondary.as_ref().clone()).await;
        let verifier = ChainLogVerifier::new(&primary_endpoint, &secondary_endpoint).unwrap();
        let observation = verifier
            .verify_fifth_legacy_binary_module_operations_interval_bounded(
                OWNER,
                LEGACY,
                100,
                100,
                &parent,
                &end,
                256,
                Duration::from_secs(10),
            )
            .await
            .unwrap();
        assert_eq!(
            observation.status(),
            &FifthLegacyBinaryModuleOperationsStatus::Matched
        );
        assert_eq!(observation.operations().len(), 1);
        assert_eq!(
            observation.operations()[0].kind(),
            FifthDirectModuleOperationKind::Split
        );
        assert_eq!(observation.operations()[0].condition_id(), condition);
        assert_eq!(observation.operations()[0].amount(), amount);
        assert_eq!(observation.operations()[0].owner_pusd_outflow(), amount);
        assert_eq!(
            observation.operations()[0].owner_position_inflows(),
            [amount; 2]
        );
        assert_eq!(observation.operations()[0].funding_transactions().len(), 1);
        assert_eq!(
            observation.block_observations()[0].module_position_balances(),
            [U256::ZERO; 2]
        );
        assert!(
            observation.block_observations()[0]
                .module_pusd_balance()
                .is_zero()
        );
        primary_task.abort();
        secondary_task.abort();
    }

    #[tokio::test]
    async fn direct_binary_module_rooted_split_merge_and_redeem_captures() {
        use super::fifth_direct_module_operations::{
            FifthDirectModuleOperationKind, FifthLegacyBinaryModuleOperationsStatus,
        };

        for case in [
            DirectModuleCase::Split,
            DirectModuleCase::Merge,
            DirectModuleCase::RedeemZero,
            DirectModuleCase::RedeemPositive,
        ] {
            let (fixture, owner, legacy, parent, end) = direct_module_case_fixture(case);
            let (primary_endpoint, primary_task) =
                serve_direct_module_fixture(fixture.clone()).await;
            let (secondary_endpoint, secondary_task) =
                serve_direct_module_fixture(fixture.clone()).await;
            let verifier = ChainLogVerifier::new(&primary_endpoint, &secondary_endpoint).unwrap();
            let observation = verifier
                .verify_fifth_legacy_binary_module_operations_interval_bounded(
                    &owner,
                    &legacy,
                    100,
                    101,
                    &parent,
                    &end,
                    130,
                    Duration::from_secs(10),
                )
                .await
                .unwrap();
            assert_eq!(fixture.requests.load(Ordering::Acquire), 130);
            assert_eq!(
                observation.status(),
                &FifthLegacyBinaryModuleOperationsStatus::Matched
            );
            assert_eq!(observation.block_observations().len(), 2);
            if matches!(case, DirectModuleCase::Split) {
                assert_eq!(
                    observation.block_observations()[0].module_pusd_balance(),
                    U256::from(10)
                );
                assert_eq!(
                    observation.block_observations()[0].module_position_balances(),
                    [U256::ZERO; 2]
                );
                assert!(
                    observation.block_observations()[1]
                        .module_pusd_balance()
                        .is_zero()
                );
                assert_eq!(
                    observation.block_observations()[1].module_position_balances(),
                    [U256::ZERO; 2]
                );
            } else {
                assert!(
                    observation
                        .block_observations()
                        .iter()
                        .all(|point| point.module_position_balances() == [U256::ZERO; 2]
                            && point.module_pusd_balance().is_zero())
                );
            }
            assert_eq!(observation.operations().len(), 1);
            let operation = &observation.operations()[0];
            match case {
                DirectModuleCase::Split => {
                    assert_eq!(operation.kind(), FifthDirectModuleOperationKind::Split);
                    assert_eq!(operation.amount(), U256::from(10));
                    assert_eq!(operation.owner_position_inflows(), [U256::from(10); 2]);
                    assert_eq!(operation.owner_pusd_outflow(), U256::from(10));
                }
                DirectModuleCase::Merge => {
                    assert_eq!(operation.kind(), FifthDirectModuleOperationKind::Merge);
                    assert_eq!(operation.amount(), U256::from(3));
                    assert_eq!(operation.owner_position_outflows(), [U256::from(3); 2]);
                    assert_eq!(operation.owner_pusd_inflow(), U256::from(3));
                }
                DirectModuleCase::RedeemZero => {
                    assert_eq!(operation.kind(), FifthDirectModuleOperationKind::Redeem);
                    assert_eq!(operation.position_id(), Some(direct_module_ids(&legacy)[0]));
                    assert_eq!(operation.payout(), Some(U256::ZERO));
                    assert_eq!(operation.owner_pusd_inflow(), U256::ZERO);
                }
                DirectModuleCase::RedeemPositive => {
                    assert_eq!(operation.kind(), FifthDirectModuleOperationKind::Redeem);
                    assert_eq!(operation.position_id(), Some(direct_module_ids(&legacy)[1]));
                    assert_eq!(operation.payout(), Some(U256::from(2)));
                    assert_eq!(operation.owner_pusd_inflow(), U256::from(2));
                }
            }
            capture_direct_module_case(case.name(), &observation, &fixture);
            primary_task.abort();
            secondary_task.abort();
        }
    }

    #[tokio::test]
