    #[tokio::test]
    async fn direct_module_interval_late_budget_and_final_proof_timeout_and_cancel() {
        use super::fifth_direct_module_operations::BoundedFifthLegacyBinaryModuleOperationsError;

        let budget_fixture = direct_module_case_fixture(DirectModuleCase::Split).0;
        let (primary, primary_task) = serve_direct_module_fixture(budget_fixture.clone()).await;
        let (secondary, secondary_task) = serve_direct_module_fixture(budget_fixture.clone()).await;
        let (opening, _, closing, _) = ctf_inventory_headers_with_102(&budget_fixture);
        assert!(matches!(
            ChainLogVerifier::new(&primary, &secondary)
                .unwrap()
                .verify_fifth_legacy_binary_module_operations_interval_bounded(
                    "0x17c5185167401ed00cf5f5b2fc97d9bbfdb7d025",
                    DIRECT_MODULE_LEGACY,
                    100,
                    101,
                    opening["hash"].as_str().unwrap(),
                    closing["hash"].as_str().unwrap(),
                    129,
                    Duration::from_secs(10),
                )
                .await,
            Err(BoundedFifthLegacyBinaryModuleOperationsError::RequestBudgetExceeded)
        ));
        assert!((128..=129).contains(&budget_fixture.requests.load(Ordering::Acquire)));
        primary_task.abort();
        secondary_task.abort();

        tokio::time::pause();
        let mut deadline_fixture = direct_module_case_fixture(DirectModuleCase::Split).0;
        deadline_fixture.initial_clock_advance_ms = Some(500);
        deadline_fixture.initial_clock_advance_once =
            std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        deadline_fixture.direct_module_boundary_proof_gate = Some(gate.clone());
        let (primary, primary_task) = serve_direct_module_fixture(deadline_fixture.clone()).await;
        let (secondary, secondary_task) =
            serve_direct_module_fixture(deadline_fixture.clone()).await;
        let (opening, _, closing, _) = ctf_inventory_headers_with_102(&deadline_fixture);
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let parent = opening["hash"].as_str().unwrap().to_owned();
        let end = closing["hash"].as_str().unwrap().to_owned();
        let clock_started = tokio::time::Instant::now();
        let mut deadline_task = tokio::spawn(async move {
            verifier
                .verify_fifth_legacy_binary_module_operations_interval_bounded(
                    "0x17c5185167401ed00cf5f5b2fc97d9bbfdb7d025",
                    DIRECT_MODULE_LEGACY,
                    100,
                    101,
                    &parent,
                    &end,
                    130,
                    Duration::from_secs(1),
                )
                .await
        });
        tokio::select! {
            result = &mut deadline_task => panic!("operation interval returned before the final module cash/role proof gate: {result:?}"),
            _ = gate.started.notified() => {},
            _ = test_wall_timeout(Duration::from_secs(30)) => panic!("final module cash/role proof gate was not reached"),
        }
        assert_eq!(
            tokio::time::Instant::now().duration_since(clock_started),
            Duration::from_millis(500)
        );
        tokio::time::advance(Duration::from_millis(600)).await;
        assert!(matches!(
            deadline_task.await.unwrap(),
            Err(BoundedFifthLegacyBinaryModuleOperationsError::Timeout)
        ));
        gate.release.send_replace(true);
        primary_task.abort();
        secondary_task.abort();
        tokio::time::resume();

        let cancel_fixture = direct_module_case_fixture(DirectModuleCase::Split).0;
        let cancel_gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        let mut cancel_fixture = cancel_fixture;
        cancel_fixture.direct_module_boundary_proof_gate = Some(cancel_gate.clone());
        let (primary, primary_task) = serve_direct_module_fixture(cancel_fixture.clone()).await;
        let (secondary, secondary_task) = serve_direct_module_fixture(cancel_fixture.clone()).await;
        let (opening, _, closing, _) = ctf_inventory_headers_with_102(&cancel_fixture);
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let parent = opening["hash"].as_str().unwrap().to_owned();
        let end = closing["hash"].as_str().unwrap().to_owned();
        let task = tokio::spawn(async move {
            verifier
                .verify_fifth_legacy_binary_module_operations_interval_bounded(
                    "0x17c5185167401ed00cf5f5b2fc97d9bbfdb7d025",
                    DIRECT_MODULE_LEGACY,
                    100,
                    101,
                    &parent,
                    &end,
                    130,
                    Duration::from_secs(30),
                )
                .await
        });
        let mut task = task;
        tokio::select! {
            result = &mut task => panic!("operation interval returned before the final module cash/role proof gate: {result:?}"),
            _ = cancel_gate.started.notified() => {},
            _ = test_wall_timeout(Duration::from_secs(30)) => panic!("caller-cancellation proof gate was not reached"),
        }
        let sent_before_abort = cancel_fixture.requests.load(Ordering::Acquire);
        task.abort();
        assert!(task.await.unwrap_err().is_cancelled());
        cancel_gate.release.send_replace(true);
        tokio::time::sleep(Duration::from_millis(50)).await;
        assert_eq!(
            cancel_fixture.requests.load(Ordering::Acquire),
            sent_before_abort
        );
        primary_task.abort();
        secondary_task.abort();
    }

    #[tokio::test]
    async fn direct_module_interval_rejects_rooted_wrong_caller_and_malformed_source_streams() {
        use super::fifth_direct_module_operations::{
            FifthLegacyBinaryModuleOperationsStatus,
            FifthLegacyBinaryModuleOperationsUnavailableReason,
        };

        let mut wrong_caller = direct_module_case_fixture(DirectModuleCase::Split).0;
        let (other_call, other_owner) = signed_polygon_call_with_seed(
            "0x3333333333333333333333333333333333333333",
            &vector_call("split-owner10"),
            1,
            [0x43; 32],
        );
        assert_ne!(other_owner, "0x17c5185167401ed00cf5f5b2fc97d9bbfdb7d025");
        wrong_caller.extra_direct_call_transaction = Some(other_call);
        let tail_logs = wrong_caller.extra_inventory_logs.as_mut().unwrap();
        let initiator = address_topic(&other_owner);
        tail_logs.last_mut().unwrap()["topics"][1] = json!(initiator);
        let report = verify_direct_module_fixture(&wrong_caller, 130, Duration::from_secs(10))
            .await
            .unwrap();
        assert!(matches!(
            report.status(),
            FifthLegacyBinaryModuleOperationsStatus::Unavailable {
                reason:
                    FifthLegacyBinaryModuleOperationsUnavailableReason::UnsupportedOwnerActivity,
                ..
            }
        ));
        assert!(report.operations().is_empty());

        for mutation in [0_u8, 1, 2] {
            let mut fixture = direct_module_case_fixture(DirectModuleCase::Split).0;
            let logs = fixture.extra_inventory_logs.as_mut().unwrap();
            match mutation {
                0 => {
                    logs.pop();
                }
                1 => {
                    logs.reverse();
                }
                _ => {
                    logs.push(logs[0].clone());
                }
            }
            let report = verify_direct_module_fixture(&fixture, 130, Duration::from_secs(10))
                .await
                .unwrap();
            assert!(matches!(
                report.status(),
                FifthLegacyBinaryModuleOperationsStatus::Unavailable {
                    reason:
                        FifthLegacyBinaryModuleOperationsUnavailableReason::SourceSettlementMismatch,
                    ..
                }
            ));
            assert!(report.operations().is_empty());
        }
    }

