    #[tokio::test]
    async fn fifth_direct_migration_refuses_same_state_control_event_roundtrips() {
        use fifth_direct_legacy_migration::{
            FifthDirectLegacyMigrationStatus, FifthDirectLegacyMigrationUnavailableReason,
        };

        const OWNER: &str = "0x17c5185167401ed00cf5f5b2fc97d9bbfdb7d025";
        const MODULE: &str = "0x3333333333333333333333333333333333333333";
        const USDCE_IMPLEMENTATION: &str = "0xdd9185db084f5c4fff3b4f70e7ba62123b812226";
        const MODULE_IMPLEMENTATION: &str = "0x2222222222222222222222222222222222222222";

        let owner_topic = address_topic(OWNER);
        let module_topic = address_topic(MODULE);
        let implementation_topic = address_topic(USDCE_IMPLEMENTATION);
        let module_implementation_topic = address_topic(MODULE_IMPLEMENTATION);
        let legacy =
            parse_fixed_b256("0x1212121212121212121212121212121212121212121212121212121212121212")
                .unwrap();
        let mut condition_bytes = [0_u8; 32];
        condition_bytes[0] = 1;
        condition_bytes[1..17].copy_from_slice(&legacy.as_slice()[16..]);
        let pair_topic = format!("{:#x}", B256::from(condition_bytes));

        let mut approval_off = raw_movement_log(
            &movement_topic("ApprovalForAll(address,address,bool)"),
            &[owner_topic.clone(), module_topic.clone()],
            movement_word(U256::ZERO),
        );
        approval_off.address = CTF_CONDITIONAL_TOKENS_ADDRESS.to_owned();
        let mut approval_on = raw_movement_log(
            &movement_topic("ApprovalForAll(address,address,bool)"),
            &[owner_topic, module_topic],
            movement_word(U256::ONE),
        );
        approval_on.address = CTF_CONDITIONAL_TOKENS_ADDRESS.to_owned();

        let mut paused = raw_movement_log(
            "0xdc9b357849b1f270abed270e8b7b026ba0a6c0a0137ad63fe62595e9a5ef338e",
            std::slice::from_ref(&pair_topic),
            movement_word(U256::ONE),
        );
        paused.address = MODULE.to_owned();
        let mut unpaused = raw_movement_log(
            "0x7c4b1aa57f3709ea7889a5749c87fea12721ab4484993ecc65c07cba4b99bd46",
            &[pair_topic],
            Vec::new(),
        );
        unpaused.address = MODULE.to_owned();

        let mut usdce_proxy_updated = raw_movement_log(
            USDC_E_PROXY_UPDATED_TOPIC,
            &[implementation_topic.clone(), implementation_topic],
            Vec::new(),
        );
        usdce_proxy_updated.address = USDC_E_PROXY_ADDRESS.to_owned();
        let mut module_upgraded = raw_movement_log(
            &movement_topic("Upgraded(address)"),
            &[module_implementation_topic],
            Vec::new(),
        );
        module_upgraded.address = MODULE.to_owned();

        let control_cases = [
            vec![approval_off, approval_on],
            vec![paused, unpaused],
            vec![usdce_proxy_updated],
            vec![module_upgraded],
        ];
        for control_logs in control_cases {
            let (mut fixture, owner, legacy) = fifth_direct_migration_fixture("unresolved-single");
            let transaction_logs = {
                let receipt_logs = fixture
                    .rooted_gas_block
                    .as_mut()
                    .unwrap()
                    .receipt_logs
                    .first_mut()
                    .unwrap();
                receipt_logs.extend(test_log_rows(control_logs));
                receipt_logs.clone()
            };
            fixture.inventory_logs = Some(transaction_logs);
            let report = verify_fifth_direct_migration_fixture(fixture, &owner, &legacy, 142)
                .await
                .unwrap();
            assert!(matches!(
                report.status(),
                FifthDirectLegacyMigrationStatus::Unavailable {
                    reason: FifthDirectLegacyMigrationUnavailableReason::ResolutionStateUnavailable,
                    ..
                }
            ));
            assert!(report.transactions().is_empty());
        }
    }

