    #[tokio::test]
    async fn fifth_direct_migration_rejects_wrong_signed_owner_calldata_and_log_sequence() {
        use fifth_direct_legacy_migration::{
            FifthDirectLegacyMigrationStatus, FifthDirectLegacyMigrationUnavailableReason,
        };

        let mut source_call_cases = Vec::new();
        let (fixture, owner, _legacy) = fifth_direct_migration_fixture("unresolved-single");
        let calldata = fixture.direct_call_transaction.as_ref().unwrap()["input"]
            .as_str()
            .unwrap();
        let calldata = hex::decode(calldata.trim_start_matches("0x")).unwrap();
        let (wrong_transaction, wrong_owner) = signed_polygon_call_with_seed(
            "0x3333333333333333333333333333333333333333",
            &calldata,
            0,
            [0x43; 32],
        );
        assert_ne!(wrong_owner, owner);
        let mut wrong_caller = fixture;
        wrong_caller.direct_call_transaction = Some(wrong_transaction.clone());
        wrong_caller.rooted_gas_block.as_mut().unwrap().transactions[0] = wrong_transaction;
        source_call_cases.push((
            wrong_caller,
            FifthDirectLegacyMigrationUnavailableReason::UnsupportedOwnerActivity,
        ));

        let (fixture, owner, legacy) = fifth_direct_migration_fixture("unresolved-single");
        let mut malformed = hex::decode(
            fixture.direct_call_transaction.as_ref().unwrap()["input"]
                .as_str()
                .unwrap()
                .trim_start_matches("0x"),
        )
        .unwrap();
        malformed[35] = 0x80;
        let (malformed_transaction, recovered_owner) =
            signed_polygon_owner_call("0x3333333333333333333333333333333333333333", &malformed, 0);
        assert_eq!(recovered_owner, owner);
        let mut malformed_fixture = fixture;
        malformed_fixture.direct_call_transaction = Some(malformed_transaction.clone());
        malformed_fixture
            .rooted_gas_block
            .as_mut()
            .unwrap()
            .transactions[0] = malformed_transaction;
        source_call_cases.push((
            malformed_fixture,
            FifthDirectLegacyMigrationUnavailableReason::InvalidCalldata,
        ));

        for (fixture, expected_reason) in source_call_cases {
            let report = verify_fifth_direct_migration_fixture(fixture, &owner, &legacy, 142)
                .await
                .unwrap();
            assert!(matches!(
                report.status(),
                FifthDirectLegacyMigrationStatus::Unavailable { reason, .. }
                    if *reason == expected_reason
            ));
            assert!(report.transactions().is_empty());
        }

        for mutation in 0..3 {
            let (mut fixture, owner, legacy) = fifth_direct_migration_fixture("unresolved-single");
            let changed_logs = {
                let logs = fixture
                    .rooted_gas_block
                    .as_mut()
                    .unwrap()
                    .receipt_logs
                    .first_mut()
                    .unwrap();
                match mutation {
                    0 => {
                        logs.remove(0);
                    }
                    1 => {
                        logs.swap(0, 1);
                    }
                    _ => {
                        logs[0]["topics"][1] =
                            json!(address_topic("0x4444444444444444444444444444444444444444"));
                    }
                }
                logs.clone()
            };
            fixture.inventory_logs = Some(changed_logs);
            let report = verify_fifth_direct_migration_fixture(fixture, &owner, &legacy, 142)
                .await
                .unwrap();
            assert!(matches!(
                report.status(),
                FifthDirectLegacyMigrationStatus::Unavailable {
                    reason: FifthDirectLegacyMigrationUnavailableReason::SourceSettlementMismatch,
                    ..
                }
            ));
            assert!(report.transactions().is_empty());
        }
    }

