    #[tokio::test]
    async fn fifth_direct_migration_rejects_ctf_usdce_and_pause_proof_mutations() {
        use fifth_direct_legacy_migration::BoundedFifthDirectLegacyMigrationError;

        const USDCE: &str = "0x2791bca1f2de4661ed88a30c99a7a9449aa84174";
        const MODULE: &str = "0x3333333333333333333333333333333333333333";
        const PAUSE_KEY: &str =
            "0x20e44ec09811b11f0215bb93bf47e210679593158275f3162378786df431dfa8";

        let mutations = [
            (CTF_CONDITIONAL_TOKENS_ADDRESS, 0_u8),
            (CTF_CONDITIONAL_TOKENS_ADDRESS, 1),
            (CTF_CONDITIONAL_TOKENS_ADDRESS, 2),
            (USDCE, 0),
            (USDCE, 1),
            (USDCE, 2),
            (MODULE, 0),
            (MODULE, 1),
            (MODULE, 2),
        ];
        for (address, mutation) in mutations {
            let (mut fixture, owner, legacy) = fifth_direct_migration_fixture("unresolved-single");
            let proof = fixture
                .fifth_code_proofs_by_block
                .as_mut()
                .unwrap()
                .get_mut(&100)
                .unwrap()
                .get_mut(&address.to_ascii_lowercase())
                .unwrap();
            match mutation {
                0 => proof["codeHash"] = json!(format!("0x{}", "99".repeat(32))),
                1 => {
                    let rows = proof["storageProof"].as_array_mut().unwrap();
                    let row = if address == MODULE {
                        rows.iter_mut().find(|row| row["key"] == PAUSE_KEY).unwrap()
                    } else {
                        &mut rows[0]
                    };
                    row["key"] = json!(format!("0x{}", "88".repeat(32)));
                }
                2 => {
                    let rows = proof["storageProof"].as_array_mut().unwrap();
                    let row = if address == MODULE {
                        rows.iter_mut().find(|row| row["key"] == PAUSE_KEY).unwrap()
                    } else {
                        &mut rows[0]
                    };
                    row["value"] = json!("0x1");
                }
                _ => {
                    let rows = proof["storageProof"].as_array_mut().unwrap();
                    let row = rows.iter_mut().find(|row| row["key"] == PAUSE_KEY).unwrap();
                    row["value"] = json!("0x1");
                }
            }
            assert!(matches!(
                verify_fifth_direct_migration_fixture(fixture, &owner, &legacy, 142).await,
                Err(BoundedFifthDirectLegacyMigrationError::Verification(
                    ChainLogAuditError::Unverified
                ))
            ));
        }
    }

