    #[tokio::test]
    async fn fifth_direct_migration_deadline_is_absolute_and_caller_abort_stops_requests() {
        use fifth_direct_legacy_migration::BoundedFifthDirectLegacyMigrationError;

        let (mut fixture, owner, legacy) = fifth_direct_migration_fixture("unresolved-single");
        tokio::time::pause();
        fixture.initial_clock_advance_ms = Some(500);
        let early_gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        let late_gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        fixture.migration_opening_proof_gate = Some(early_gate.clone());
        fixture.migration_late_proof_gate = Some(late_gate.clone());
        let (opening, _, end, _) = ctf_inventory_headers_with_102(&fixture);
        let primary = ctf_inventory_provider(fixture.clone()).await;
        let secondary = ctf_inventory_provider(fixture.clone()).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let task_owner = owner.clone();
        let task_legacy = legacy.clone();
        let clock_started = tokio::time::Instant::now();
        let mut deadline_task = tokio::spawn(async move {
            verifier
                .verify_fifth_direct_legacy_migration_interval_bounded(
                    &task_owner,
                    &task_legacy,
                    100,
                    101,
                    opening["hash"].as_str().unwrap(),
                    end["hash"].as_str().unwrap(),
                    142,
                    Duration::from_secs(1),
                )
                .await
        });
        wait_for_identity_proof_gate(&early_gate, &mut deadline_task, Duration::from_secs(30))
            .await;
        assert_eq!(
            tokio::time::Instant::now().duration_since(clock_started),
            Duration::from_millis(500),
            "fixture must consume half the virtual deadline before the final proof"
        );
        early_gate.release.send_replace(true);
        wait_for_identity_proof_gate(&late_gate, &mut deadline_task, Duration::from_secs(30)).await;
        tokio::time::advance(Duration::from_millis(600)).await;
        let deadline_result = tokio::select! {
            result = &mut deadline_task => result.unwrap(),
            _ = test_wall_timeout(Duration::from_secs(30)) => panic!("deadline result did not settle after advancing past its deadline"),
        };
        late_gate.release.send_replace(true);
        assert!(matches!(
            deadline_result,
            Err(BoundedFifthDirectLegacyMigrationError::Timeout)
        ));
        tokio::time::resume();

        let (mut fixture, owner, legacy) = fifth_direct_migration_fixture("unresolved-single");
        let late_gate = std::sync::Arc::new(CtfIdentityProofGate::new());
        fixture.migration_late_proof_gate = Some(late_gate.clone());
        let (opening, _, end, _) = ctf_inventory_headers_with_102(&fixture);
        let primary = ctf_inventory_provider(fixture.clone()).await;
        let secondary = ctf_inventory_provider(fixture.clone()).await;
        let verifier = ChainLogVerifier::new(&primary, &secondary).unwrap();
        let task_owner = owner.clone();
        let task_legacy = legacy.clone();
        let mut cancelled_task = tokio::spawn(async move {
            verifier
                .verify_fifth_direct_legacy_migration_interval_bounded(
                    &task_owner,
                    &task_legacy,
                    100,
                    101,
                    opening["hash"].as_str().unwrap(),
                    end["hash"].as_str().unwrap(),
                    142,
                    Duration::from_secs(10),
                )
                .await
        });
        wait_for_identity_proof_gate(&late_gate, &mut cancelled_task, Duration::from_secs(30))
            .await;
        cancelled_task.abort();
        assert!(cancelled_task.await.unwrap_err().is_cancelled());
        let sends_at_abort = fixture.requests.load(Ordering::Relaxed);
        late_gate.release.send_replace(true);
        test_wall_timeout(Duration::from_millis(50)).await;
        assert_eq!(fixture.requests.load(Ordering::Relaxed), sends_at_abort);
    }

    fn capture_fifth_legacy_inventory_case(
        case: &str,
        fixture: &CtfInventoryFixture,
        report: &FifthLegacyBinaryInventoryObservation,
        owner: &str,
        legacy: &str,
        parent_hash: &Value,
        end_hash: &Value,
    ) {
        let Ok(directory) = std::env::var("PDH_CAPTURE_FIFTH_LEGACY_INVENTORY_DIRECTORY") else {
            return;
        };
        if std::env::var("PDH_CAPTURE_FIFTH_LEGACY_INVENTORY_CASE")
            .is_ok_and(|requested| requested != case)
        {
            return;
        }
        let mut unique = BTreeMap::new();
        for row in fixture.rpc_capture.lock().unwrap().iter() {
            let key = serde_json::to_string(&json!([row["method"], row["params"]])).unwrap();
            if let Some(previous) = unique.insert(key, row.clone()) {
                assert_eq!(previous["result"], row["result"]);
            }
        }
        let opening = report.opening().selected_balances();
        let blocks = report.block_observations().iter().map(|point| json!({
            "block_number":point.selected_balances().block_number(),
            "block_hash":point.selected_balances().block_hash(),
            "state_root":point.selected_balances().state_root(),
            "position_balances":[format!("{:#x}",point.selected_balances().position_balance_a()),format!("{:#x}",point.selected_balances().position_balance_b())],
            "pusd_balance":format!("{:#x}",point.selected_balances().pusd_balance()),
            "v2_condition_id":format!("{:#x}",point.v2_condition_id()),
            "v2_position_ids":point.v2_position_ids().map(|id| format!("{id:#x}")),
            "legacy_position_ids":point.legacy_position_ids().map(|id| format!("{id:#x}")),
            "module_proxy":format!("{:#x}",point.module_proxy()),
            "module_implementation":format!("{:#x}",point.module_implementation()),
            "module_implementation_code_hash":format!("{:#x}",point.module_implementation_code_hash()),
            "ctf_state":format!("{:?}",point.ctf_condition_state().status()),
        })).collect::<Vec<_>>();
        let envelope = json!({
            "provenance":"Synthetic root-consistent Polygon signed-transaction/receipt fixture captured from loopback RPC only; no VM or external chain retrieval.",
            "case":case,"owner":owner,"legacy_condition_id":legacy,
            "from_block":100,"through_block":101,
            "parent_hash":parent_hash,"end_hash":end_hash,
            "opening":{"block_number":opening.block_number(),"block_hash":opening.block_hash(),"state_root":opening.state_root(),"position_balances":[format!("{:#x}",opening.position_balance_a()),format!("{:#x}",opening.position_balance_b())],"pusd_balance":format!("{:#x}",opening.pusd_balance())},
            "block_observations":blocks,"selected_owner_transfer_entries":report.selected_owner_transfer_entries(),
            "source_policy_version":report.source_policy_version(),"rpc_responses":unique.into_values().collect::<Vec<_>>(),
        });
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../")
            .join(directory)
            .join(format!("fifth-legacy-inventory-{case}-rpc.json"));
        use std::io::Write as _;
        std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(path)
            .unwrap()
            .write_all(&serde_json::to_vec(&envelope).unwrap())
            .unwrap();
    }

