    fn fifth_source_module_event(
        split: bool,
        condition_id: B256,
        amount: u64,
        index: u64,
    ) -> ChainReceiptLog {
        use std::str::FromStr;
        let exchange = super::fifth_code_context::EXCHANGE_PROXY;
        let signature = if split {
            "PositionsSplit(address,bytes31,address,address,uint256)"
        } else {
            "PositionsMerged(address,bytes31,address,uint256)"
        };
        let indexed = vec![
            test_address_topic(exchange),
            format!("{condition_id:#x}"),
            test_address_topic(exchange),
        ];
        let mut data = Vec::new();
        if split {
            data.extend_from_slice(&[0_u8; 12]);
            data.extend_from_slice(Address::from_str(exchange).unwrap().as_slice());
        }
        data.extend(movement_word(U256::from(amount)));
        test_indexed_event_log(
            "0x3333333333333333333333333333333333333333",
            &movement_topic(signature),
            &indexed,
            data,
            index,
        )
    }

    fn fifth_source_order_filled(
        order: &FifthMatchOrder,
        hash: B256,
        taker: Address,
        maker_amount: u64,
        taker_amount: u64,
        fee: u64,
        index: u64,
    ) -> ChainReceiptLog {
        let mut data = Vec::new();
        for word in [
            U256::from(match order.side {
                FifthOrderSide::Buy => 0_u64,
                FifthOrderSide::Sell => 1_u64,
            }),
            order.token_id,
            U256::from(maker_amount),
            U256::from(taker_amount),
            U256::from(fee),
            U256::from_be_bytes(order.builder.0),
            U256::from_be_bytes(order.metadata.0),
        ] {
            data.extend(movement_word(word));
        }
        test_indexed_event_log(
            super::fifth_code_context::EXCHANGE_PROXY,
            &movement_topic(
                "OrderFilled(bytes32,address,address,uint8,uint256,uint256,uint256,uint256,bytes32,bytes32)",
            ),
            &[
                format!("{hash:#x}"),
                test_address_topic(&format!("{:#x}", order.maker)),
                test_address_topic(&format!("{taker:#x}")),
            ],
            data,
            index,
        )
    }

    fn fifth_source_taker_events(
        order: &FifthMatchOrder,
        hash: B256,
        making: u64,
        taking: u64,
        fee: u64,
        index: u64,
    ) -> [ChainReceiptLog; 2] {
        use std::str::FromStr;
        let fill = fifth_source_order_filled(
            order,
            hash,
            Address::from_str(super::fifth_code_context::EXCHANGE_PROXY).unwrap(),
            making,
            taking,
            fee,
            index,
        );
        let mut matched_data = Vec::new();
        for word in [
            U256::from(match order.side {
                FifthOrderSide::Buy => 0_u64,
                FifthOrderSide::Sell => 1_u64,
            }),
            order.token_id,
            U256::from(making),
            U256::from(taking),
        ] {
            matched_data.extend(movement_word(word));
        }
        let matched = test_indexed_event_log(
            super::fifth_code_context::EXCHANGE_PROXY,
            &movement_topic("OrdersMatched(bytes32,address,uint8,uint256,uint256,uint256)"),
            &[
                format!("{hash:#x}"),
                test_address_topic(&format!("{:#x}", order.maker)),
            ],
            matched_data,
            index + 1,
        );
        [fill, matched]
    }

