    #[tokio::test]
    async fn fifth_legacy_binary_interval_allows_first_resolution_but_refuses_payout_rewrite() {
        let (fixture, owner, legacy) = fifth_legacy_inventory_fixture(false);
        let resolved_values = [
            U256::from(2_u64),
            U256::from(4_u64),
            U256::ONE,
            U256::from(3_u64),
        ];
        let changed_values = [
            U256::from(2_u64),
            U256::from(4_u64),
            U256::from(3_u64),
            U256::ONE,
        ];
        let (resolved_root, resolved_proofs) =
            fifth_legacy_binary_balances::test_rooted_point_proof_packet_with_identity(
                [U256::from(100_u64), U256::from(200_u64)],
                U256::from(1000_u64),
                &format!("0x{}", "22".repeat(20)),
                resolved_values,
            );
        let mut allowed = fixture.clone();
        allowed.post_state = Some((resolved_root.clone(), Value::Null));
        allowed.extra_post_state = Some((resolved_root.clone(), Value::Null));
        let proof_map = allowed.fifth_code_proofs_by_block.as_mut().unwrap();
        proof_map.insert(100, resolved_proofs.clone());
        proof_map.insert(101, resolved_proofs.clone());
        let (opening, _, end, _) = ctf_inventory_headers_with_102(&allowed);
        let primary = ctf_inventory_provider(allowed.clone()).await;
        let secondary = ctf_inventory_provider(allowed).await;
        let matched = ChainLogVerifier::new(&primary, &secondary)
            .unwrap()
            .verify_fifth_legacy_binary_inventory_interval_bounded(
                &owner,
                &legacy,
                100,
                101,
                opening["hash"].as_str().unwrap(),
                end["hash"].as_str().unwrap(),
                1000,
                Duration::from_secs(10),
            )
            .await
            .unwrap();
        assert_eq!(matched.status(), &FifthLegacyBinaryInventoryStatus::Matched);

        let (changed_root, changed_proofs) =
            fifth_legacy_binary_balances::test_rooted_point_proof_packet_with_identity(
                [U256::from(100_u64), U256::from(200_u64)],
                U256::from(1000_u64),
                &format!("0x{}", "22".repeat(20)),
                changed_values,
            );
        let mut rewritten = fixture;
        rewritten.post_state = Some((resolved_root.clone(), Value::Null));
        rewritten.extra_post_state = Some((changed_root, Value::Null));
        let proof_map = rewritten.fifth_code_proofs_by_block.as_mut().unwrap();
        proof_map.insert(100, resolved_proofs);
        proof_map.insert(101, changed_proofs);
        let (opening, _, end, _) = ctf_inventory_headers_with_102(&rewritten);
        let primary = ctf_inventory_provider(rewritten.clone()).await;
        let secondary = ctf_inventory_provider(rewritten).await;
        let result = ChainLogVerifier::new(&primary, &secondary)
            .unwrap()
            .verify_fifth_legacy_binary_inventory_interval_bounded(
                &owner,
                &legacy,
                100,
                101,
                opening["hash"].as_str().unwrap(),
                end["hash"].as_str().unwrap(),
                1000,
                Duration::from_secs(10),
            )
            .await;
        assert_eq!(
            result,
            Err(BoundedFifthLegacyBinaryInventoryError::Verification(
                ChainLogAuditError::Unverified
            ))
        );
    }

