    #[tokio::test]
    async fn fifth_legacy_binary_interval_marks_malformed_underflow_and_overflow_unavailable() {
        use super::fifth_code_context::POSITION_MANAGER_PROXY;

        let legacy =
            parse_fixed_b256("0x1212121212121212121212121212121212121212121212121212121212121212")
                .unwrap();
        let v2 =
            B256::from_slice(&[&[1_u8][..], &legacy.as_slice()[16..], &[0_u8; 15][..]].concat());
        let selected_id = U256::from_be_bytes(v2.0);
        let mut malformed = ctf_raw_single(0x11, 0x22, selected_id, U256::ONE);
        malformed.address = POSITION_MANAGER_PROXY.to_owned();
        malformed.data = "0x00".to_owned();
        let mut underflow = ctf_raw_single(0x11, 0x22, selected_id, U256::from(101_u64));
        underflow.address = POSITION_MANAGER_PROXY.to_owned();
        let mut overflow = ctf_raw_single(0x22, 0x11, selected_id, U256::ONE);
        overflow.address = POSITION_MANAGER_PROXY.to_owned();

        for (case, logs, opening_positions, expected_reason) in [
            (
                "malformed",
                vec![malformed],
                [U256::from(100_u64), U256::from(200_u64)],
                None,
            ),
            (
                "underflow",
                vec![underflow],
                [U256::from(100_u64), U256::from(200_u64)],
                Some(FifthLegacyBinaryInventoryUnavailableReason::BalanceUnderflow),
            ),
            (
                "overflow",
                vec![overflow],
                [U256::MAX, U256::from(200_u64)],
                Some(FifthLegacyBinaryInventoryUnavailableReason::BalanceOverflow),
            ),
        ] {
            let (fixture, owner, legacy) = fifth_legacy_inventory_fixture_with(
                false,
                opening_positions,
                U256::from(1000_u64),
                logs,
            );
            let (opening, _, end, _) = ctf_inventory_headers_with_102(&fixture);
            let primary = ctf_inventory_provider(fixture.clone()).await;
            let secondary = ctf_inventory_provider(fixture.clone()).await;
            let report = ChainLogVerifier::new(&primary, &secondary)
                .unwrap()
                .verify_fifth_legacy_binary_inventory_interval_bounded(
                    &owner,
                    &legacy,
                    100,
                    101,
                    opening["hash"].as_str().unwrap(),
                    end["hash"].as_str().unwrap(),
                    1000,
                    Duration::from_secs(10),
                )
                .await
                .unwrap();
            let FifthLegacyBinaryInventoryStatus::Unavailable {
                block_number,
                asset,
                reason,
            } = report.status()
            else {
                panic!(
                    "expected an unavailable whole-interval result, got {:?}",
                    report.status()
                );
            };
            assert_eq!(*block_number, 100);
            assert_eq!(*asset, FifthLegacyBinaryInventoryAsset::PositionA);
            if let Some(expected_reason) = expected_reason {
                assert_eq!(*reason, expected_reason);
            } else {
                assert!(matches!(
                    reason,
                    FifthLegacyBinaryInventoryUnavailableReason::UnsupportedMovement(_)
                ));
            }
            assert_eq!(report.selected_owner_transfer_entries(), None);
            if case == "malformed" {
                capture_fifth_legacy_inventory_case(
                    case,
                    &fixture,
                    &report,
                    &owner,
                    &legacy,
                    &opening["hash"],
                    &end["hash"],
                );
            }
        }
    }

