    #[tokio::test]
    async fn paired_inventory_refuses_bad_proxy_state_and_bounds_all_calls_once() {
        let token_id = test_token_id();
        let owner = format!("0x{}", "11".repeat(20));
        for bad_slot in [0_usize, 1] {
            let mut fixture = ctf_inventory_fixture_with_paired_events(
                Some(U256::from(1_u64)),
                U256::from(1_u64),
                U256::from(10_u64),
                U256::from(10_u64),
                vec![],
                0,
            );
            fixture.post_usdc_proofs.as_mut().unwrap().0["storageProof"][bad_slot]["value"] =
                json!("0x0");
            let (opening, closing, _) = ctf_inventory_headers(&fixture);
            let first = ctf_inventory_provider(fixture.clone()).await;
            let second = ctf_inventory_provider(fixture.clone()).await;
            let verifier = ChainLogVerifier::new(&first, &second).unwrap();
            let result = await_loopback_without_virtual_time_advance(
                verifier.verify_paired_asset_inventory_reconciliation_bounded(
                    &owner,
                    token_id,
                    100,
                    100,
                    opening["hash"].as_str().unwrap(),
                    closing["hash"].as_str().unwrap(),
                    50,
                    Duration::from_secs(5),
                ),
            )
            .await;
            assert_eq!(
                result,
                Err(BoundedPairedAssetInventoryError::Verification(
                    ChainLogAuditError::Unverified
                ))
            );
        }

        let limited = ctf_inventory_fixture_with_paired_events(
            Some(U256::from(1_u64)),
            U256::from(1_u64),
            U256::from(10_u64),
            U256::from(10_u64),
            vec![],
            0,
        );
        let (opening, closing, _) = ctf_inventory_headers(&limited);
        let first = ctf_inventory_provider(limited.clone()).await;
        let second = ctf_inventory_provider(limited.clone()).await;
        let verifier = ChainLogVerifier::new(&first, &second).unwrap();
        let result = await_loopback_without_virtual_time_advance(
            verifier.verify_paired_asset_inventory_reconciliation_bounded(
                &owner,
                token_id,
                100,
                100,
                opening["hash"].as_str().unwrap(),
                closing["hash"].as_str().unwrap(),
                49,
                Duration::from_secs(5),
            ),
        )
        .await;
        assert_eq!(
            result,
            Err(BoundedPairedAssetInventoryError::RequestBudgetExceeded)
        );
        assert!(limited.requests.load(Ordering::Relaxed) <= 49);

        let slow = ctf_inventory_fixture_with_paired_events(
            Some(U256::from(1_u64)),
            U256::from(1_u64),
            U256::from(10_u64),
            U256::from(10_u64),
            vec![],
            15,
        );
        let (opening, closing, _) = ctf_inventory_headers(&slow);
        let first = ctf_inventory_provider(slow.clone()).await;
        let second = ctf_inventory_provider(slow.clone()).await;
        let verifier = ChainLogVerifier::new(&first, &second).unwrap();
        assert_eq!(
            verifier
                .verify_paired_asset_inventory_reconciliation_bounded(
                    &owner,
                    token_id,
                    100,
                    100,
                    opening["hash"].as_str().unwrap(),
                    closing["hash"].as_str().unwrap(),
                    100,
                    Duration::from_millis(5)
                )
                .await,
            Err(BoundedPairedAssetInventoryError::Timeout)
        );
        let task = tokio::spawn(async move {
            verifier
                .verify_paired_asset_inventory_reconciliation_bounded(
                    &owner,
                    token_id,
                    100,
                    100,
                    opening["hash"].as_str().unwrap(),
                    closing["hash"].as_str().unwrap(),
                    100,
                    Duration::from_secs(10),
                )
                .await
        });
        tokio::time::sleep(Duration::from_millis(25)).await;
        task.abort();
        assert!(task.await.unwrap_err().is_cancelled());
        let sent = slow.requests.load(Ordering::Relaxed);
        tokio::time::sleep(Duration::from_millis(50)).await;
        assert_eq!(slow.requests.load(Ordering::Relaxed), sent);
    }

