        let fixture = usdc_e_fixture(
            root.clone(),
            proxy_proof,
            implementation_proof,
            101,
            "0x89",
            0,
        );
        let first = usdc_e_balance_provider(fixture.clone()).await;
        let second = usdc_e_balance_provider(fixture.clone()).await;
        let observation = ChainLogVerifier::new(&first, &second)
            .unwrap()
            .verify_usdc_e_proxy_balance_bounded(
                &format!("{:#x}", test_owner()),
                100,
                &expected_hash,
                10,
                Duration::from_secs(3),
            )
            .await
            .unwrap();
        assert_eq!(observation.balance(), balance);
        assert_eq!(observation.decimals(), 6);
